import { useCallback, useEffect } from 'react';

import { LayoutDOMEvent, mapContentComponentState } from '@common/utils/layout';

import type { AttachedPageInternal } from '@common/api/pages/enterprise-shapes';

/**
 * Adds views to the interop context group 'CONTEXT_GROUP_PAGE' when a tab is created.
 *
 * @param containerId The id of the container element
 */
export const useAddViewsToInteropContextGroups = (containerId: string, page: AttachedPageInternal) => {
    const addViewContextGroups = useCallback(
        async (event: Extract<LayoutDOMEvent, { type: 'tab-created' | 'tab-closed' }>) => {
            try {
                const viewIdentity = { uuid: fin.me.uuid, name: event.detail.name };
                console.debug('addViewContextGroups:', viewIdentity.name, page.contextGroup ?? 'CONTEXT_GROUP_PAGE');
                fin.me.interop.joinContextGroup(page.contextGroup ?? 'CONTEXT_GROUP_PAGE', viewIdentity);
            } catch (err) {
                console.warn(err);
                // Either fin is not injected or we are too early
                // onClientConnected in the interopoverride will handle when we are too early
            }
        },
        [page.contextGroup]
    );
    useEffect(() => {
        const container: any = document.getElementById(containerId);
        container.addEventListener('tab-created', addViewContextGroups);

        (async () => {
            const layout = fin.Platform.Layout.wrapSync({
                layoutName: page.layoutContainerKey,
                name: fin.me.name,
                uuid: fin.me.uuid
            });
            let layoutConfig;
            try {
                layoutConfig = await layout.getConfig();
            } catch (error) {
                // may error if not yet created, we can ignore this
            }

            if (layoutConfig) {
                const views = mapContentComponentState(layoutConfig.content);
                views.forEach((view) => {
                    const viewIdentity = { uuid: fin.me.uuid, name: view.name };
                    console.debug(
                        'Adding view to context group:',
                        viewIdentity.name,
                        page.contextGroup ?? 'CONTEXT_GROUP_PAGE'
                    );
                    fin.me.interop.joinContextGroup(page.contextGroup ?? 'CONTEXT_GROUP_PAGE', viewIdentity);
                });
            }
        })();

        return () => {
            container.removeEventListener('tab-created', addViewContextGroups);
        };
    }, [addViewContextGroups, containerId, page.contextGroup, page.layoutContainerKey]);
};
