import type OpenFin from '@openfin/core';

/**
 * Synchronous snapshot of window options at creation time (OpenFin runtime).
 * Prefer this before layout snapshot / GL create when Redux must match initial `workspacePlatform`
 * (e.g. page list and pin state) without waiting for async `getOptions()`.
 *
 * @see WindowOptionsProvider — same source as React context pre-seed.
 */
export const getInitialWindowOptions = (): OpenFin.WindowOptions | null => {
    if (typeof fin === 'undefined') {
        return null;
    }
    // @ts-expect-error undocumented OpenFin runtime property
    return fin.__internal_?.initialOptions ?? null;
};
