import { MutableRefObject, useCallback, useEffect, useRef, useState } from 'react';

import OpenFin from '@openfin/core';

import { connectToBookmarkDialogChannel } from '@common/utils/enterprise-channels';
import { BookmarkDialogChannelMessage, PopupWindowMenuType } from '@common/utils/popup-window';
import { getWindowBounds } from '@common/utils/window';

import { useEnterpriseBookmarkDialogWindow } from '@enterprise/hooks/EnterpriseSearchMenu/useEnterpriseBookmarkDialogWindow';

/*
 * This hook is used to show the Add/Edit Bookmark dialog when the user clicks on the bookmark icon in the search view.
 * It also listens for the response from the dialog and updates the state to indicate if the bookmark was updated or created.
 * @param bookmarkIconRef - The ref of the bookmark icon element
 * @param selectedView - The selected view to bookmark
 * @returns {showDialog, isDialogShown, bookmarkUpdatedOrCreated}
 */
export const useAddEditBookmarkDialog = (
    bookmarkIconRef: MutableRefObject<HTMLElement | null>,
    selectedView?: OpenFin.View
) => {
    const [isDialogShown, setIsDialogShown] = useState(false);
    const [isBookmarkUpdatedOrCreated, setIsBookmarkUpdatedOrCreated] = useState(false);
    const channelRef = useRef<OpenFin.ChannelClient | null>(null);

    useEffect(() => {
        setIsBookmarkUpdatedOrCreated(false);
    }, [selectedView]);

    useEnterpriseBookmarkDialogWindow();

    const showDialog = useCallback(async () => {
        if (!bookmarkIconRef.current || !selectedView || isDialogShown) {
            return;
        }

        if (!channelRef.current) {
            channelRef.current = await connectToBookmarkDialogChannel();
            channelRef.current.register('response', (e: any) => {
                if (e.type !== 'cancel') {
                    setIsBookmarkUpdatedOrCreated((prev) => !prev);
                }
                if (e.type !== 'bookmark-created') {
                    // when bookmark is created the dialog is still shown
                    setIsDialogShown(false);
                }
            });
        }

        const bookmarkIconRect = bookmarkIconRef.current.getBoundingClientRect();
        const browserWindow = fin.Window.getCurrentSync();
        const browserWindowBounds = await getWindowBounds(browserWindow);
        await channelRef.current.dispatch('open', {
            parentIdentity: fin.me.identity,
            type: PopupWindowMenuType.AddEditBookmark,
            responseIdentity: fin.me.identity,
            x: browserWindowBounds.left + bookmarkIconRect.left,
            y: browserWindowBounds.top + bookmarkIconRect.top + bookmarkIconRect.height,
            payload: { selectedViewIdentity: selectedView?.identity }
        } as BookmarkDialogChannelMessage);

        setIsDialogShown(true);
    }, [bookmarkIconRef, selectedView, isDialogShown]);

    useEffect(() => {
        // Cleanup function to disconnect from the channel when the component unmounts
        return () => {
            if (channelRef.current) {
                channelRef.current.disconnect();
                channelRef.current = null; // Clean up the ref
            }
        };
    }, []);

    return { showDialog, isDialogShown, isBookmarkUpdatedOrCreated };
};
