import { FC, memo, useCallback, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { RightMenuConfig } from '@common/utils/menu-config';
import { enterpriseToolbarTestIds } from '@common/utils/test-ids';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import ExtendedButton from '@enterprise/components/ControlBar/BaseButton/ExtendedButton';

import * as WP from '@client-platform/index';
import { BrowserButtonType } from '@client-platform/shapes';
import { useLanguageChange } from '@common/hooks/useLanguageChange';

import { defaultButtonPropMap } from '../../../utils';
import { getSaveMenu } from '../../menus/menuConfig';
import { PredefinedIconUrl } from '../MenuButtonIcon';

interface Props {
    tooltip?: string;
    iconUrl?: string;
}

const ContextMenuWidth = 150;

const SaveButton: FC<Props> = ({ tooltip, iconUrl }) => {
    const [menuConfig, setMenuConfig] = useState<RightMenuConfig | null>(null);
    const customToolTip = tooltip || menuConfig?.title;
    const defaultIcon = defaultButtonPropMap[BrowserButtonType.SaveMenu].iconProps.icon;

    const buttonRef = useRef<HTMLButtonElement | null>(null);
    const [isActive, setIsActive] = useState(false);

    const activePage = useSelector(selectActivePage);

    const onLanguageChange = useCallback(() => {
        getSaveMenu().then((menu) => setMenuConfig(menu));
    }, []);

    useLanguageChange(onLanguageChange);

    const onClickHandler = async () => {
        if (!buttonRef.current) {
            throw new Error('Unable to open Save Menu (SaveButton): buttonRef.current is null');
        }

        setIsActive(true);

        const currOFWindow = fin.Window.getCurrentSync();

        const { bottom: buttonBottom, left: buttonLeft } = buttonRef.current.getBoundingClientRect();

        // eslint-disable-next-line no-underscore-dangle
        await WP.getCurrentSync()
            .Browser.wrapSync(currOFWindow.identity)
            ._openSaveButtonContextMenu({
                x: buttonLeft + buttonRef.current.offsetWidth / 2 - ContextMenuWidth / 2,
                y: buttonBottom,
                buttonLeft,
                buttonWidth: buttonRef.current.offsetWidth,
                pageId: activePage.pageId
            });
        setIsActive(false);
    };

    return (
        <ExtendedButton
            title={customToolTip}
            active={isActive}
            onClick={onClickHandler}
            ref={buttonRef}
            data-testid={enterpriseToolbarTestIds.saveButton}
        >
            <PredefinedIconUrl customIconUrl={iconUrl} uiLibIcon={defaultIcon} />
        </ExtendedButton>
    );
};

export default memo(SaveButton);
