import type OpenFin from '@openfin/core';

import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { getViewUrl } from './utils';

export const raiseBrowserFocusViewAnalyticsEvent = async (
    identity: OpenFin.Identity,
    selectedViews: OpenFin.Identity[]
) => {
    if (selectedViews.every((id) => !(id.name === identity.name && id.uuid === identity.uuid))) {
        raiseBrowserAnalytics({
            type: 'View',
            action: 'Focus View',
            value: identity.name,
            data: { uuid: identity.uuid, url: await getViewUrl(identity) }
        });
    }
};

export const raiseBrowserBlurViewAnalyticsEvent = (identity: OpenFin.Identity, selectedViews: OpenFin.Identity[]) => {
    selectedViews.forEach(async (id: OpenFin.Identity) => {
        if (!(id.name === identity.name && id.uuid === identity.uuid)) {
            raiseBrowserAnalytics({
                type: 'View',
                action: 'Blur View',
                value: id.name,
                data: { uuid: id.uuid, url: await getViewUrl(id) }
            });
        }
    });
};
