import React, { FC } from 'react';

import { IconSizeType, IconType } from '@openfin/ui-library';

import { CustomIcon } from '@common/components/Icon/CustomIcon';

import { StyledIcon } from '@common/styles/svg-icons';
interface Props {
    'customIconUrl'?: string;
    'uiLibIcon'?: IconType;
    'disabled'?: boolean;
    'size'?: IconSizeType;
    'data-testid'?: string;
}
export const PredefinedIconUrl: FC<Props> = ({ customIconUrl, uiLibIcon, disabled, size, ...rest }) => {
    return customIconUrl ? (
        <CustomIcon iconURL={customIconUrl} size={size} {...rest} />
    ) : (
        <StyledIcon disabled={disabled} icon={uiLibIcon} size={size} {...rest} />
    );
};
