import { useCallback, useEffect } from 'react';
import { useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import { makeNewLandingPage } from '@common/utils/landing-page';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';
import { currentOFIdentity } from '@common/utils/window';

import { selectIsWindows } from '@common/slices/environment';

import { savePageAsHandler, savePageHandler } from '@client-platform/api/context-menu/utils';
import { requestCloseBrowserWindow } from '@enterprise/api/controls';

import { BrowserCreateWindowRequest, getCurrentSync } from '@client-platform/index';

const createNewTab = async () => {
    const newPage = await makeNewLandingPage();
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
    await browser.addPage(newPage);
    await browser.setActivePage(newPage.pageId);
    raiseBrowserAnalytics({
        type: 'HotKey',
        action: 'NewPage',
        entityId: currentOFIdentity
    });
};

const createNewWindow = async () => {
    const page = await makeNewLandingPage();
    const pages = [page];
    const options: BrowserCreateWindowRequest = {
        workspacePlatform: {
            pages,
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            windowType: 'enterprise'
        }
    };
    console.debug('createNewWindow', options);
    const platform = getCurrentSync();
    await platform.Browser.createWindow(options);
    raiseBrowserAnalytics({
        type: 'HotKey',
        action: 'NewWindow',
        entityId: currentOFIdentity
    });
};

const restoreTab = async () => {
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
    // eslint-disable-next-line no-underscore-dangle
    browser._restoreRemovedTab();
    raiseBrowserAnalytics({
        type: 'HotKey',
        action: 'RestorePage',
        entityId: currentOFIdentity
    });
};

const savePage = async () => {
    await savePageHandler(currentOFIdentity);
};

const savePageAs = async () => {
    await savePageAsHandler(currentOFIdentity);
};

export const processHotKeys = (
    e: OpenFin.Events.ViewEvents.HotkeyEvent,
    isOsWindows: boolean,
    viewId?: OpenFin.Identity
) => {
    if (e.inputType === 'keyDown') {
        switch (e.code) {
            case 'KeyT':
                e.shiftKey ? restoreTab() : createNewTab();
                break;
            case 'KeyS':
                e.shiftKey ? savePageAs() : savePage();
                break;
            case 'KeyN':
                createNewWindow();
                break;
            case 'KeyW':
                requestCloseBrowserWindow();
                break;
            case 'BracketRight':
                if (!isOsWindows) {
                    const view = viewId ? fin.View.wrapSync(viewId) : undefined;
                    view && view.navigateForward();
                }
                break;
            case 'BracketLeft':
                if (!isOsWindows) {
                    const view = viewId ? fin.View.wrapSync(viewId) : undefined;
                    view && view.navigateBack();
                }
                break;
            default:
                break;
        }
    }
};

const useEnterpriseHotkeys = (viewId?: OpenFin.Identity) => {
    const isWindows = useSelector(selectIsWindows);
    const onHotKeys = useCallback(
        (e: any) => {
            processHotKeys(e, isWindows, viewId);
        },
        [isWindows, viewId]
    );

    useEffect(() => {
        const win = fin.Window.wrapSync(currentOFIdentity);
        win.addListener('hotkey', onHotKeys);
        return () => {
            win.removeListener('hotkey', onHotKeys);
        };
    }, [onHotKeys]);
};

export default useEnterpriseHotkeys;
