import { useEffect, useMemo, useState } from 'react';

import { searchBookmark } from '@enterprise/components/ControlBar/SearchMenu/utils';

const combineBeacons = (beacons: (any | undefined)[]): string => {
    return beacons.map((beacon) => beacon).join('-');
};

export const useIsBookmarked = (url?: string, ...beacons: (any | undefined)[]) => {
    const [isBookmarked, setIsBookmarked] = useState(false);
    const combinedBeacons = useMemo(() => combineBeacons(beacons), [beacons]);

    useEffect(() => {
        if (url) {
            searchBookmark(url).then((e) => setIsBookmarked(!!e));
        } else {
            setIsBookmarked(false);
        }
    }, [url, combinedBeacons]);

    return isBookmarked;
};
