import { useEffect, useState } from 'react';

import OpenFin from '@openfin/core';

export const useGetContextGroups = () => {
    const [contextGroups, setContextGroups] = useState<OpenFin.ContextGroupInfo[]>([]);

    useEffect(() => {
        fin.me.interop.getContextGroups().then((groups) => setContextGroups(groups));
    }, []);

    return contextGroups;
};
