import { useEffect, useRef, useState } from 'react';

import { OpenFin } from '@openfin/core';

const useFocusedViewListeners = (focusedView: { view: OpenFin.View } | null) => {
    const viewRef = useRef<OpenFin.View | null>(null);
    const [isContentLoading, setIsContentLoading] = useState<boolean>(false);

    const onFinishLoad = () => {
        setIsContentLoading(false);
    };

    const onUrlChange = (e: OpenFin.WebContentsEvents.UrlChangedEvent) => {
        if (!e.isInPage) {
            setIsContentLoading(true);
        }
    };

    useEffect(() => {
        if (!focusedView) return;

        const selectedView = focusedView.view;
        if (!selectedView) return;

        if (viewRef.current?.identity.name === selectedView.identity.name) {
            return;
        }

        // clean up listeners from previous view
        if (viewRef.current) {
            viewRef.current.removeListener('did-finish-load', onFinishLoad);
            viewRef.current.removeListener('url-changed', onUrlChange);
        }

        // attach new listeners
        selectedView.addListener('did-finish-load', onFinishLoad);
        selectedView.addListener('url-changed', onUrlChange);

        // update ref
        viewRef.current = selectedView;

        return () => {
            if (viewRef.current) {
                viewRef.current.removeListener('did-finish-load', onFinishLoad);
                viewRef.current.removeListener('url-changed', onUrlChange);
                viewRef.current = null;
            }
        };
        // depend on view identity to avoid unnecessary renders
    }, [focusedView?.view.identity.name]); // eslint-disable-line react-hooks/exhaustive-deps

    return { isContentLoading, setIsContentLoading };
};

export default useFocusedViewListeners;
