import { useEffect } from 'react';
import { useDispatch } from 'react-redux';

import { OpenFin } from '@openfin/core';

import { getEnterpriseLandingUrl } from '@common/utils/browser-base-url';

import { removeViewIcon, viewStartedLoading, viewStoppedLoading } from '@enterprise/slices/view-tab-icons';

export function useTabLoadingEvents() {
    const dispatch = useDispatch();
    const currentWindow = fin.Window.getCurrentSync();

    useEffect(() => {
        // Handle URL changes in the view
        async function handleViewUrlChanged(
            e: OpenFin.WindowEvents.ByType<'view-url-changed'> & { viewIdentity: OpenFin.Identity }
        ) {
            try {
                const view = fin.View.wrapSync(e.viewIdentity);
                const LANDING_PAGE_URL = await getEnterpriseLandingUrl();
                if (!e.isInPage) {
                    const info = await view.getInfo();
                    const newUrl = info.url || '';
                    if (LANDING_PAGE_URL && newUrl.startsWith(LANDING_PAGE_URL)) {
                        handleDidStopLoading(e as any);
                    } else {
                        dispatch(viewStartedLoading({ viewName: e.viewIdentity.name }));
                    }
                }
            } catch (err) {
                console.warn('Could not get view info:', err);
            }
        }
        // Handle the event when a view has stopped loading
        function handleDidStopLoading(
            e: OpenFin.WindowEvents.ByType<'view-did-finish-load'> & { viewIdentity: OpenFin.Identity }
        ) {
            dispatch(viewStoppedLoading({ viewName: e.viewIdentity.name }));
        }

        // Handle the event when a view fails to load (equivalent to `did-finish-load`, but triggered on failure)
        function handleDidFailLoad(
            e: OpenFin.WindowEvents.ByType<'view-did-fail-load'> & { viewIdentity: OpenFin.Identity }
        ) {
            dispatch(viewStoppedLoading({ viewName: e.viewIdentity.name }));
        }
        function handleViewDetached(
            e: OpenFin.WindowEvents.ByType<'view-detached'> & { viewIdentity: OpenFin.Identity }
        ) {
            dispatch(removeViewIcon({ viewName: e.viewIdentity.name }));
        }

        currentWindow.addListener('view-url-changed', handleViewUrlChanged);
        currentWindow.addListener('view-did-finish-load', handleDidStopLoading);
        currentWindow.addListener('view-did-fail-load', handleDidFailLoad);
        currentWindow.addListener('view-detached', handleViewDetached);

        return () => {
            currentWindow.removeListener('view-url-changed', handleViewUrlChanged);
            currentWindow.removeListener('view-did-finish-load', handleDidStopLoading);
            currentWindow.removeListener('view-did-fail-load', handleDidFailLoad);
            currentWindow.removeListener('view-detached', handleViewDetached);
        };
    }, [dispatch]);
}
