import React from 'react';
import { useSelector } from 'react-redux';

import styled from 'styled-components';

import { Box } from '@openfin/ui-library';

import { enterpriseToolbarTestIds } from '@common/utils/test-ids';

import { selectIsWindows } from '@common/slices/environment';

import NotificationsButton from '@common/components/NotificationsButton/NotificationsButton';

import AICompanionShortcutButton from '@enterprise/components/ControlBar/AICompanionShortcutButton/AICompanionShortcutButton';
import EnterpriseGlobalMenu from '@enterprise/components/ControlBar/EnterpriseGlobalMenu/EnterpriseGlobalMenu';

import useIsNotificationsRunning from '@common/hooks/useIsNotificationsRunning';
import useWindowFocusState from '@common/hooks/useWindowFocusState';
import { useEnterpriseSettings } from '@enterprise/context/EnterpriseSettings';

import BookmarksPanelButton from '../BookmarksPanelButton/BookmarksPanelButton';

import ToolbarContainer from './ToolbarContainer/ToolbarContainer';
import WindowStateContainer from './WindowStateContainer/WindowStateContainer';

/**
 * Top level container component for Browsers navigation buttons.
 */
const RightControlsContainer: React.FC = () => {
    const isWindows = useSelector(selectIsWindows);
    const windowFocused = useWindowFocusState();

    const isNotificationsRunning = useIsNotificationsRunning();
    const { aiCompanion, bookmarks } = useEnterpriseSettings();

    return (
        <Container className="right-controls-container">
            <ToolbarContainer />
            {isNotificationsRunning && (
                <NotificationsButton
                    windowFocused={windowFocused}
                    data-testid={enterpriseToolbarTestIds.notificationsButton}
                />
            )}
            {aiCompanion.enabled && <AICompanionShortcutButton />}
            {bookmarks.enabled && <BookmarksPanelButton />}
            <EnterpriseGlobalMenu />
            {/* Window state buttons on top-right for Windows */}
            {isWindows && <WindowStateContainer />}
        </Container>
    );
};

export default RightControlsContainer;

const Container = styled(Box)`
    display: flex;
    align-items: center;
    flex-shrink: 0;

    margin-right: 0px;
    border-bottom: 1px solid var(--color-enterprise-top-chrome-border);
`;
