import { currentOFIdentity, maxOrRestore } from '@common/utils/window';

import { StyledIcon } from '@common/styles/svg-icons';

import IconButton from '../IconButton/IconButton';
import { CustomIcon } from '../Icon/CustomIcon';

export const toggleMaximize = () => {
    maxOrRestore(currentOFIdentity).catch((err) => {
        console.error(`failed to maximize or restore: ${err}`);
    });
};

export type MaximizeButtonProps = {
    disabled?: boolean;
    tooltip: string;
    iconUrl?: string;
    analyticsCallback?: (action: string, windowName?: string) => void;
};

export const MaximizeButton = ({ disabled = false, iconUrl, tooltip, analyticsCallback }: MaximizeButtonProps) => {
    const onClick = analyticsCallback
        ? () => {
              analyticsCallback(tooltip, currentOFIdentity.name);
              toggleMaximize();
          }
        : toggleMaximize;

    return (
        <IconButton title={tooltip} onClick={onClick} disabled={disabled}>
            {iconUrl ? (
                <CustomIcon iconURL={iconUrl} size="small" />
            ) : (
                <StyledIcon disabled={disabled} icon="SizeIcon" size="small" />
            )}
        </IconButton>
    );
};
