import React, { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { SearchMenuChannelMessage } from '@common/utils/popup-window';
import { currentOFIdentity, WindowName } from '@common/utils/window';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectLayoutsWithSelectedViews } from '@enterprise/slices/tab-focus';

import { useInitChannelToSearchMenuView } from '@enterprise/hooks/EnterpriseSearchMenu/useInitChannelToSearchMenuView';
import { usePostMessageToSearchMenuView } from '@enterprise/hooks/EnterpriseSearchMenu/usePostMessageToSearchMenuView';
import useSearchMenuViewLifecycleManager from '@enterprise/hooks/EnterpriseSearchMenu/useSearchMenuViewLifecycleManager';
import { useUpdateViewExpansionState } from '@enterprise/hooks/EnterpriseSearchMenu/useUpdateViewExpansionState';
import useEnterpriseHotkeys from '@enterprise/hooks/useEnterpriseHotkeys';

import { AddressBarInput } from './AddressBarInput';

export const searchMenuIdentity = {
    uuid: currentOFIdentity.uuid,
    name: WindowName.BrowserAddressSearchPrefix + currentOFIdentity.name
};

export type SecureIconState = { shouldShow: boolean; isSecureSite: boolean };

export type SearchMenuChannel = {
    postMessage: (message: SearchMenuChannelMessage) => void;
};

const AddressBar: React.FC = () => {
    // Active Page and Views
    const activePage = useSelector(selectActivePage);
    const layoutsWithSelectedViews = useSelector(selectLayoutsWithSelectedViews);
    const selectedViews = layoutsWithSelectedViews[activePage.layoutContainerKey];

    // Search view communication and state
    const searchMenuChannel = useRef<SearchMenuChannel>({
        postMessage: (message) => console.warn('Attempted to send message before search menu was ready:', message)
    });
    const [addressBarWidth, setAddressBarWidth] = useState<number>(null);

    // Address bar content
    const addressBarInputRef = useRef<HTMLInputElement>(null);
    const inputContainerRef = useRef<HTMLDivElement>(null);
    const [searchText, setSearchText] = useState<string>('');
    const [isSecure, setIsSecure] = useState<SecureIconState>({ shouldShow: true, isSecureSite: true });

    useEffect(() => {
        (async () => {
            const addressSearchResultsView = fin.View.wrapSync(searchMenuIdentity);
            await addressSearchResultsView.setBounds({ top: 0, left: 0, width: 0, height: 0 });
            await addressSearchResultsView.attach({ uuid: fin.me.uuid, name: fin.me.name });
            await addressSearchResultsView.hide();
        })();
    }, [searchMenuIdentity]);

    const { sendKeyboardEventToSearchMenuView } = usePostMessageToSearchMenuView(
        selectedViews,
        searchMenuChannel.current,
        activePage,
        searchText,
        inputContainerRef
    );

    useEnterpriseHotkeys(selectedViews && selectedViews.length > 0 ? selectedViews[0] : undefined);

    const { selectedViewUrl, resetAddressBarToSelectedViewUrl } = useSearchMenuViewLifecycleManager(
        searchText,
        selectedViews,
        addressBarInputRef,
        isSecure,
        setSearchText,
        setIsSecure
    );

    const { announcementMessage } = useInitChannelToSearchMenuView(
        selectedViews,
        selectedViewUrl,
        searchMenuChannel.current,
        setAddressBarWidth,
        setSearchText,
        resetAddressBarToSelectedViewUrl
    );

    useUpdateViewExpansionState(setAddressBarWidth, resetAddressBarToSelectedViewUrl);

    return (
        <AddressBarInput
            addressSearchResultsViewIdentity={searchMenuIdentity}
            addressBarInputRef={addressBarInputRef}
            inputContainerRef={inputContainerRef}
            addressBarWidth={addressBarWidth}
            isSecure={isSecure}
            setSearchText={setSearchText}
            searchText={searchText}
            sendKeyboardEventToSearchMenuView={sendKeyboardEventToSearchMenuView}
            resetAddressBarToSelectedViewUrl={resetAddressBarToSelectedViewUrl}
            announcementMessage={announcementMessage}
        />
    );
};

export default AddressBar;
