import React from 'react';

import styled from 'styled-components';

import { Box } from '@openfin/ui-library';

import { ThemedSVG } from '@enterprise/styles/ThemedSVG';

import { SecureIconState } from '../LeftControlsContainer/EnterpriseNavigationContainer/AddressBar/AddressBar';

const LockContainer = styled(Box)`
    padding: 4px 2px;
    border-radius: ${({ theme }) => theme.radius.small};
    svg {
        fill: var(--color-enterprise-search-bar-icon-default);

        path {
            fill: var(--color-enterprise-search-bar-icon-default);
        }
    }
`;

export const SecureIcon: React.FC<{ isSecure: SecureIconState }> = ({ isSecure }) => {
    const Icon = isSecure.shouldShow ? (isSecure.isSecureSite ? LockIcon : DangerIcon) : React.Fragment;
    return (
        <LockContainer className="secure-icon-container" title={isSecure.isSecureSite ? '' : 'Insecure content'}>
            <Icon />
        </LockContainer>
    );
};

