import { Dispatch, SetStateAction, useContext, useEffect, useRef } from 'react';

import { OpenFin } from '@openfin/core';

import debounce from 'lodash.debounce';

import {
    blurAddressBar,
    getAddressBarInputElement,
    handleAddressBarFocusForLandingPage
} from '@common/utils/address-bar-focus';
import { createInlineDebugLogger } from '@common/utils/debug-log';
import { getCurrentOFWindow, showAndFocus, WindowName } from '@common/utils/window';

import { BrowserChannelAction, getBrowserChannelClient } from '@common/api/protocol/browser';

import { selectIsModalOpen } from '@common/slices/modal';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import { focusManager } from '@common/services/focus-manager';
import { FOCUS_PRIORITY } from '@common/types/focus';
import { WindowSearchMenuContext } from '@enterprise/context/SearchMenu/WindowSearchMenuContext';
import store from '@enterprise/store';

import { getSearchMenuWidth } from './AdjustSearchMenuDimensions/getDimensions';
import { searchViewReady } from './useInitChannelToSearchMenuView';

const logSearchMenuDebug = createInlineDebugLogger('search-menu-debug');

type WindowBlurredOrViewFocusedEvent =
    | Extract<OpenFin.WindowEvents.WindowEvent, { type: 'view-focused' }>
    | OpenFin.WebContentsEvents.BlurredEvent;

export let lastViewEvent: { viewIdentity: OpenFin.Identity; type: 'view-focused' | 'tab-created' } = null;

export const resetLastFocusedView = () => {
    lastViewEvent = null;
};

let focusSearchViewAfterWindowBlurTimeout: ReturnType<typeof setTimeout> | null = null;

/**
 * This function enables the following behaviors:
 *  - When a new view tab is created via the new tab button that is on the landing page, the address input will focus.
 *  - When a user clicks on an inactive view tab on the landing page, the address input will focus.
 *  - When a user clicks on an active view tab on the landing page while the address input bar is focused, the view will focus.
 *
 * Returns true if address bar input is focused, false otherwise.
 */
export const debouncedHandleAddressFocusOnLandingPage = debounce(
    async (
        { viewIdentity, type }: typeof lastViewEvent,
        /**
         * A producer function that should return modal state from redux
         * to ensure fresh state given this function is debounced
         */
        isModalOpen: () => boolean = () => false
    ) => {
        const isEventOnSameView = lastViewEvent?.viewIdentity.name === viewIdentity.name;

        // If there is no lastViewEvent, or if the event wasn't on the same view
        // AND there is no open modal in our redux store
        if ((!lastViewEvent || !isEventOnSameView) && !isModalOpen()) {
            lastViewEvent = { viewIdentity, type };
            // Use common utility for address bar focus
            return handleAddressBarFocusForLandingPage(viewIdentity, isModalOpen);
        } else if (!viewIdentity.name.startsWith(WindowName.BrowserAddressSearchPrefix)) {
            // Focusing on a view doesn't change the document.activeElement, so we must explicitly blur the input.
            // This will prevent the address bar from refocusing if a user tabs away from and then back to the browser window.
            blurAddressBar();
        }
        return false;
    },
    150
);

/**
 * This function enables the following behaviors:
 *  - When a user re-organizes a view tab on the landing page in a layout, the address input will focus.
 *  - When a user drags a page tab that is on the landing page into a layout, the address input will focus.
 *  - When a user drags out a view or page tab on the landing page to create a new window, the address input will focus (from 'tab-created' event).
 */
export const resetLastFocusedViewAndHandleViewFocused = async (
    event: typeof lastViewEvent,
    isModalOpen: () => boolean = () => false
) => {
    lastViewEvent = null;
    return debouncedHandleAddressFocusOnLandingPage(event, isModalOpen);
};

/**
 * This function handles the blurring of search view when a user blurs the browser window.
 * NOTE: This function is only being exported to prevent typecheck error. It is not currently used, but we will preserve
 * it in case any requirements change in the behavior of the search menu on window blur.
 */
export const handleBrowserWindowBlurred = (event: WindowBlurredOrViewFocusedEvent, callback: () => void) => {
    if (event.type === 'blurred') {
        focusSearchViewAfterWindowBlurTimeout = setTimeout(() => {
            callback();
        }, 150);
    } else if (event.type === 'view-focused') {
        clearTimeout(focusSearchViewAfterWindowBlurTimeout);
    }
};

/**
 * Custom hook that responds to updates to view expansion state updates, handles view focus events, and controls focus on the search input.
 *
 * @param {Dispatch<SetStateAction<number>>} setAddressBarWidth - Function that updates the width in pixels of the address input bar in its expanded state.
 * @param {() => void} resetAddressBarToSelectedViewUrl - Function to reset the address bar with the selected view's URL.
 */
export const useUpdateViewExpansionState = (
    setAddressBarWidth: Dispatch<SetStateAction<number>>,
    resetAddressBarToSelectedViewUrl: () => void
) => {
    const { shouldExpandMenu, setShouldExpandMenu } = useContext(WindowSearchMenuContext);
    const shouldExpandMenuRef = useRef(shouldExpandMenu.shouldExpand);
    const isSearchShortcutInvoked = useRef<boolean>(false);
    const resetAddressBarRef = useRef(resetAddressBarToSelectedViewUrl);

    // Keep ref in sync without triggering listener re-registration
    useEffect(() => {
        resetAddressBarRef.current = resetAddressBarToSelectedViewUrl;
    }, [resetAddressBarToSelectedViewUrl]);

    useEffect(() => {
        shouldExpandMenuRef.current = shouldExpandMenu.shouldExpand;
    }, [shouldExpandMenu.shouldExpand]);

    useEffect(() => {
        const focusInputAndExpandSearchView = async () => {
            isSearchShortcutInvoked.current = true;

            // Calling window focus via the API will implicitly trigger a view-focus event. Reset the last focused view
            // tracker before calling focus to avoid an immediate search menu blur from the viewFocusListener below.
            resetLastFocusedView();

            try {
                // Promise resolves when search menu completes handshake with browser window. Avoids race condition.
                await searchViewReady.promise;

                // Use FocusManager to coordinate with other focus operations (e.g., view focus from useViewFocusCoordination)
                // Address bar has higher inherent type priority than view, so it will cancel any pending view focus
                focusManager.requestFocus({
                    target: { type: 'addressBar' },
                    priority: FOCUS_PRIORITY.ADDRESS_BAR,
                    source: 'programmatic'
                });

                setShouldExpandMenu({ shouldExpand: true, method: 'click' });
                await showAndFocus(fin.me);
            } finally {
                // Delay resetting the flag to ensure late view-focused events from showAndFocus are still guarded
                // TODO: Replace this timeout with a deterministic signal that confirms all resulting view-focused events have completed
                setTimeout(() => {
                    isSearchShortcutInvoked.current = false;
                }, 200);
            }
        };

        const initializeChannel = async () => {
            const browserChannel = await getBrowserChannelClient();
            browserChannel.register(BrowserChannelAction.FocusAndExpandSearchInternal, focusInputAndExpandSearchView);
        };

        initializeChannel();
    }, []);

    useEffect(() => {
        const viewFocusListener = async (
            event: Extract<OpenFin.WindowEvents.WindowEvent, { type: 'view-focused' }>
        ) => {
            const isAddressSearchView = event.viewIdentity.name.startsWith(WindowName.BrowserAddressSearchPrefix);

            // If search menu is currently expanded, any non-search view focus should collapse it,
            // even if tab-focus state has not yet caught up for that newly focused view.
            if (shouldExpandMenuRef.current && !isAddressSearchView) {
                logSearchMenuDebug('collapse-search-menu-on-view-focus-expanded-menu', {
                    view: event.viewIdentity.name
                });
                setShouldExpandMenu({ shouldExpand: false });
            }

            const activePage = selectActivePage(store.getState());
            const selectedViews = selectSelectedViewsForPage(store.getState(), activePage.pageId);
            const isSelectedViewInActivePage = selectedViews.some(({ name }) => name === event.viewIdentity.name);
            logSearchMenuDebug('view-focused', {
                view: event.viewIdentity.name,
                activePageId: activePage.pageId,
                selectedViews: selectedViews.map(({ name }) => name).join('|'),
                isSelectedViewInActivePage,
                shouldExpandMenu: shouldExpandMenuRef.current
            });

            // In some cases, when dragging out a view from an active page to create a new page level tab, the newly focused view
            // from the now previously active page will fire a view-focus event. We want to ignore these events.
            if (!isSelectedViewInActivePage) {
                logSearchMenuDebug('view-focused-ignored-not-selected', {
                    view: event.viewIdentity.name
                });
                return;
            }

            // During search menu opening, ignore view-focused events to prevent premature menu closure
            // (the flag is reset in focusInputAndExpandSearchView's finally block, so all events during opening are ignored)
            if (isSearchShortcutInvoked.current) {
                logSearchMenuDebug('view-focused-during-search-shortcut', {
                    view: event.viewIdentity.name
                });
                lastViewEvent = event;
                // Re-focus address bar since the view-focused event steals focus from it
                const addressBar = getAddressBarInputElement();
                if (addressBar) {
                    addressBar.focus();
                }
                return;
            }

            if (!isAddressSearchView) {
                logSearchMenuDebug('collapse-search-menu-on-view-focus', {
                    view: event.viewIdentity.name
                });
                // Focusing on a view doesn't change the document.activeElement, so we must explicitly close the view.
                // Whether the address bar should blur is determined in debouncedHandleAddressFocusOnLandingPage().
                setShouldExpandMenu({ shouldExpand: false });

                // Reset the address bar text to the selected view's URL when refocusing on the selected view
                // or if the last selected view was the search menu.
                if (
                    lastViewEvent?.viewIdentity.name === event.viewIdentity.name ||
                    lastViewEvent?.viewIdentity.name.startsWith(WindowName.BrowserAddressSearchPrefix)
                ) {
                    resetAddressBarRef.current();
                }
            }

            // Only focus address bar when switching views, not when clicking into already-selected view
            const isAlreadySelectedView =
                selectedViews.length === 1 && selectedViews[0].name === event.viewIdentity.name;
            if (!isAlreadySelectedView) {
                debouncedHandleAddressFocusOnLandingPage(event, () => selectIsModalOpen(store.getState()));
            }
        };

        const window = getCurrentOFWindow();
        window.addListener('view-focused', viewFocusListener);

        return () => {
            // TODO WRK-4956: Unawaited promises in react hook disposers can cause global rejections
            window.removeListener('view-focused', viewFocusListener);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        if (shouldExpandMenu.shouldExpand) {
            (async () => {
                const { width: parentWindowWidth } = await getCurrentOFWindow().getBounds();
                setAddressBarWidth(getSearchMenuWidth(parentWindowWidth));
            })();
        }
    }, [shouldExpandMenu.shouldExpand]);
};
