import { useEffect, useRef } from 'react';

import type OpenFin from '@openfin/core';

/**
 * Hook to update tab aria-labels when view titles change.
 * Listens to view-page-title-updated window events and updates all tabs.
 */
export const useViewTitleUpdates = (
    containerRef: React.RefObject<HTMLDivElement>,
    setTabAccessibility: (tab: HTMLElement, closeButton: HTMLElement | null) => void
): void => {
    const setTabAccessibilityRef = useRef(setTabAccessibility);
    setTabAccessibilityRef.current = setTabAccessibility;

    useEffect(() => {
        const handleViewTitleUpdated = () => {
            if (!containerRef.current) return;

            // Find all tabs and update their aria-labels
            const tabs = containerRef.current.querySelectorAll<HTMLElement>('.lm_tab');
            tabs.forEach((tab) => {
                const closeButton = tab.querySelector('.lm_close_tab') as HTMLElement | null;
                setTabAccessibilityRef.current(tab, closeButton);
            });
        };

        const win = fin.me as OpenFin.Window;
        win.on('view-page-title-updated', handleViewTitleUpdated);

        return () => {
            win.removeListener('view-page-title-updated', handleViewTitleUpdated);
        };
    }, [containerRef]);
};
