import { useCallback, useEffect, useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import { useFocusManager } from '@common/hooks/useFocusManager';
import { isLandingPageOrEmpty } from '@common/utils/enterpriseBrowser';
import { trimUrl } from '@common/utils/url';

import { SecureIconState } from '@enterprise/components/ControlBar/LeftControlsContainer/EnterpriseNavigationContainer/AddressBar/AddressBar';

/**
 * Custom hook that manages the contents of the address input as users interact with the browser and navigate views.
 * This hook handles the auto-focusing the address input on the landing page, registers handlers for view URL changes,
 * and manages the state of the secure icon displayed next to valid addresses.
 *
 * @param searchText - String representing the current text in the address input.
 * @param selectedViews - Array of currently selected views in the browser window.
 * @param addressBarInputRef - Ref object associated with the address input DOM element.
 * @param isSecure - Object describing whether the currently focused view's site is secure and whether to show an icon in the address bar.
 * @param setSearchText - Function that updates the search text.
 * @param setIsSecure - Function that updates whether the currently focused view's site is secure and whether to show an icon in the address bar.
 * @returns Object containing the selected URL and a function to update the address bar with the selected view's URL.
 */
const useSearchMenuViewLifecycleManager = (
    searchText: string,
    selectedViews: OpenFin.Identity[],
    addressBarInputRef: React.MutableRefObject<HTMLInputElement>,
    isSecure: SecureIconState,
    setSearchText: React.Dispatch<React.SetStateAction<string>>,
    setIsSecure: React.Dispatch<React.SetStateAction<SecureIconState>>
) => {
    const selectedViewRef = useRef<OpenFin.View>(null);
    const [selectedViewUrl, setSelectedViewUrl] = useState<string>('');
    const { focusView } = useFocusManager();

    const updateAddressBarWithUrl = useCallback((url: string) => {
        const isLanding = isLandingPageOrEmpty(url);
        setIsSecure({ isSecureSite: url.startsWith('https'), shouldShow: !isLanding });
        setSelectedViewUrl(url);
        setSearchText(isLanding ? '' : url);
    }, []);

    const resetAddressBarToSelectedViewUrl = useCallback(() => {
        if (addressBarInputRef.current?.value !== trimUrl(selectedViewUrl) || !isSecure.shouldShow) {
            updateAddressBarWithUrl(selectedViewUrl);
        }
    }, [selectedViewUrl, isSecure.shouldShow]);

    const handleViewUrlChanged = useCallback(
        (event: OpenFin.WebContentsEvents.UrlChangedEvent & { viewIdentity?: OpenFin.Identity }) => {
            updateAddressBarWithUrl(event.url);

            if (!isLandingPageOrEmpty(event.url)) {
                // Focuses view when navigating from landing page to a site
                focusView(event.viewIdentity, 'navigation');
            }
        },
        [focusView, updateAddressBarWithUrl]
    );

    const initializeAddressBar = useCallback(async () => {
        if (selectedViews && selectedViews.length > 0) {
            const selectedView = await fin.View.wrap(selectedViews[0]);
            if (selectedViewRef.current?.identity.name !== selectedView.identity.name && selectedView) {
                selectedViewRef.current = selectedView;
                selectedViewRef.current.addListener('url-changed', handleViewUrlChanged);

                // Update the address bar content with newly selected view's URL
                const { url } = await selectedViewRef.current.getInfo();
                updateAddressBarWithUrl(url);
            }
        }
    }, [selectedViews, addressBarInputRef, selectedViewRef]);

    useEffect(() => {
        const previouslySelectedView = selectedViewRef.current;
        if (
            selectedViews?.length &&
            selectedViews[0] &&
            previouslySelectedView?.identity.name !== selectedViews[0].name
        ) {
            previouslySelectedView?.removeListener('url-changed', handleViewUrlChanged);
        }

        initializeAddressBar();
    }, [selectedViews, initializeAddressBar, handleViewUrlChanged]);

    useEffect(() => {
        const { shouldShow, isSecureSite } = isSecure;
        if (searchText !== selectedViewUrl && shouldShow) {
            // Hide secure icon when user modifies contents of address bar in any way
            setIsSecure({ isSecureSite, shouldShow: false });
        }
    }, [searchText]);

    return { selectedViewUrl, resetAddressBarToSelectedViewUrl };
};

export default useSearchMenuViewLifecycleManager;
