const disabledNoop = () => {
    // noop on purpose
};

interface windowButtonAnalyticsType {
    analyticsCallback?: (action: string, windowName: string) => void;
}

// eslint-disable-next-line react/display-name
const getWindowStateOrDisabledButton =
    (
        type: Exclude<BrowserButtonType, 'Custom' | 'Maximise'>,
        isWindows = true
    ): React.FC<PreDefinedButtonConfig & windowButtonAnalyticsType> =>
    // eslint-disable-next-line react/display-name
    (prop: PreDefinedButtonConfig & windowButtonAnalyticsType) => {
        if (!defaultButtonPropMap[type]) return undefined;
        const windowFocused = useWindowFocusState();
        const { disabled } = prop;
        const { t } = useTranslation();
        const isEnterprise = true;

        const handleCloseClick = useCallback(() => {
            requestCloseBrowserWindow();
        }, []);

        const onClick = useMemo(() => {
            if (disabled) return disabledNoop;

            if (prop.type === BrowserButtonType.Minimise) {
                return prop.analyticsCallback
                    ? () => {
                          prop.analyticsCallback('Minimize Window', currentOFIdentity.name);
                          handleMinimizeClick();
                      }
                    : handleMinimizeClick;
            }

            if (prop.type === BrowserButtonType.Close) {
                return handleCloseClick;
            }

            console.error(`No onClick handler for button type: ${prop.type}`);

            return undefined;
        }, [disabled, prop.type, prop.analyticsCallback, handleCloseClick]);

        const getButtonTooltip = () => {
            return prop.tooltip || (disabled ? 'Disabled' : t(defaultButtonPropMap[type].tooltipKey));
        };
        const [buttonTooltip, setButtonTooltip] = useState(getButtonTooltip());

        const onLanguageChange = useCallback(() => {
            setButtonTooltip(getButtonTooltip());
        }, []);

        useLanguageChange(onLanguageChange);

        const buttonIconUrl = prop.iconUrl;

        if (isWindows) {
            const size = 24;
            const ButtonComponent = type === BrowserButtonType.Close ? WindowChromeCloseBaseButton : BaseButton;

            return (
                <ButtonComponent title={buttonTooltip} disabled={disabled} onClick={onClick} width={size} height={size}>
                    {buttonIconUrl ? (
                        <CustomIcon customIconUrl={buttonIconUrl} />
                    ) : (
                        <StyledIcon
                            disabled={disabled}
                            isEnterprise={isEnterprise}
                            windowFocused={windowFocused}
                            {...defaultButtonPropMap[type].iconProps}
                        />
                    )}
                </ButtonComponent>
            );
        } else {
            // Enterprise on Mac
            const MacIcon = useMemo(() => {
                let TypeIcon: any;
                if (windowFocused) {
                    TypeIcon = prop.parentHover
                        ? defaultButtonPropMap[type].macIconHover
                        : defaultButtonPropMap[type].macIcon;
                } else {
                    TypeIcon = defaultButtonPropMap[type].macIconInactive;
                }
                return <TypeIcon />;
            }, [windowFocused, prop.parentHover, type]);

            const className = useMemo(
                () =>
                    windowFocused
                        ? prop.type === BrowserButtonType.Minimise
                            ? enterpriseStyles.windowControlsMacButtonMinimize
                            : enterpriseStyles.windowControlsMacButtonClose
                        : enterpriseStyles.windowControlsMacButtonInactive,
                [windowFocused, prop.type]
            );

            return (
                <MacWindowStateButton
                    className={className}
                    title={buttonTooltip}
                    disabled={disabled}
                    onClick={onClick}
                    width={12}
                    height={12}
                    hoverless
                    borderRadius="small"
                >
                    {MacIcon}
                </MacWindowStateButton>
            );
        }
    };

const defaultButtonsMap = {
    [BrowserButtonType.ColorLinking]: ColorLinkingButton,
    [BrowserButtonType.PresetLayouts]: LayoutsMenuButton,
    [BrowserButtonType.SaveMenu]: SaveMenuButton,
    // Pls keep me for backwards compatibility with < v7
    [BrowserButtonType.SavePage]: SaveMenuButton,
    [BrowserButtonType.ShowHideTabs]: ShowHideTabsButton,
    [BrowserButtonType.LockUnlockPage]: LockUnlockButton,
    [BrowserButtonType.Download]: () => null as any, // Download button is not supported in Enterprise
    [BrowserButtonType.Minimise]: getWindowStateOrDisabledButton(BrowserButtonType.Minimise),
    [BrowserButtonType.Maximise]: MaximizeButton,
    [BrowserButtonType.Close]: getWindowStateOrDisabledButton(BrowserButtonType.Close)
};

export const RightControlsButton: FC<ToolbarButton & { windowState?: WindowState }> = (config) => {
    const { t } = useTranslation();
    const isWindows = useSelector(selectIsWindows);

    useEffect(() => {
        defaultButtonsMap[BrowserButtonType.Minimise] = getWindowStateOrDisabledButton(
            BrowserButtonType.Minimise,
            isWindows
        );
        defaultButtonsMap[BrowserButtonType.Close] = getWindowStateOrDisabledButton(BrowserButtonType.Close, isWindows);
    }, [isWindows]);

    const analytics = useCallback((action: { id: string }) => {
        raiseBrowserAnalytics({
            type: 'Toolbar',
            action: 'Select Toolbar Item',
            value: action.id,
            data: { uuid: currentOFIdentity.uuid }
        });
    }, []);

    const windowButtonAnalytics = useCallback((action: string, windowName: string) => {
        raiseBrowserAnalytics({
            type: 'Window',
            action: action,
            value: windowName
        });
    }, []);

    if (config.type === BrowserButtonType.Custom) {
        return (
            <NoDragWrapper>
                <CustomButton
                    tooltip={config.tooltip}
                    iconUrl={config.iconUrl}
                    action={config.action}
                    disabled={config.disabled}
                    analyticsCallback={analytics}
                    toolbarIconButton
                />
            </NoDragWrapper>
        );
    }

    if (config.type === BrowserButtonType.Maximise) {
        const defaultTooltipTranslation =
            config.windowState === 'maximized' ? t('toolbar.restoreWindow') : t('toolbar.maximizeWindow');

        return (
            <NoDragWrapper>
                <EnterpriseMaximizeButton
                    disabled={config.disabled}
                    iconUrl={config.iconUrl}
                    tooltip={config.tooltip ?? defaultTooltipTranslation}
                    analyticsCallback={windowButtonAnalytics}
                    parentHover={config.parentHover}
                />
            </NoDragWrapper>
        );
    }

    let DefaultButton;
    if (config.disabled) {
        DefaultButton = getWindowStateOrDisabledButton(config.type, isWindows);
    } else {
        DefaultButton = defaultButtonsMap[config.type] || ((): null => null);
    }

    return (
        <NoDragWrapper>
            <DefaultButton {...(config as any)} />
        </NoDragWrapper>
    );
};

