import React from 'react';
import { useTranslation } from 'react-i18next';

import { enterpriseToolbarTestIds } from '@common/utils/test-ids';

import AICompanionIcon from '@enterprise/assets/icons/ai-companion.svg';

import useWindowFocusState from '@common/hooks/useWindowFocusState';
import { SidePanelComponent, useSidePanelContext } from '@enterprise/context/SidePanelContext';
import { IconButtonContainer } from '@enterprise/styles/buttons';

const AICompanionShortcutButton = () => {
    const { t } = useTranslation();
    const windowFocused = useWindowFocusState();
    const { isSidePanelOpen, activeComponent, toggleSidePanelComponent } = useSidePanelContext();

    return (
        <IconButtonContainer
            title={t('sidePanel.openAiCenter')}
            windowFocused={windowFocused}
            onClick={() => toggleSidePanelComponent(SidePanelComponent.AICompanion)}
            selected={isSidePanelOpen && activeComponent === SidePanelComponent.AICompanion}
            data-testid={enterpriseToolbarTestIds.aiCompanionButton}
        >
            <AICompanionIcon />
        </IconButtonContainer>
    );
};

export default AICompanionShortcutButton;
