import React, { FC, useCallback, useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import styled from 'styled-components';

import { Icon } from '@openfin/ui-library';

import { currentOFIdentity } from '@common/utils/window';

import { useTranslation } from '@common/api/i18next';
import { getTabsHandler } from '@common/api/tabs';

import BaseButton from '@common/components/BaseButton/BaseButton';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { PredefinedIconUrl } from '@enterprise/components/ControlBar/RightControlsContainer/ToolbarContainer/buttons/MenuButtonIcon';
import { handleShowHideTabs } from '@enterprise/components/ControlBar/RightControlsContainer/utils';

import { ShowHideTabsConfig } from '@client-platform/index';

const ShowHideTabsButton: FC<ShowHideTabsConfig> = ({ tabsHiddenIconUrl, tabsShownIconUrl }) => {
    const [isShowingTabs, setIsShowingTabs] = useState(true);
    const activePage = useSelector(selectActivePage);
    const pageIsLocked = !!activePage.isLocked;
    const buttonRef = useRef<HTMLButtonElement>(null);
    const { t } = useTranslation();

    useEffect(() => {
        const win = fin.Window.getCurrentSync();
        const updateIsShowingTabs = async () => {
            const tabHandler = getTabsHandler({ ...currentOFIdentity, layoutName: activePage.layoutContainerKey });
            const isShowing = await tabHandler.isShowingTabs();
            setIsShowingTabs(isShowing);
        };
        win.addListener('layout-ready', updateIsShowingTabs);
        return () => {
            win.removeListener('layout-ready', updateIsShowingTabs);
        };
    }, [activePage]);

    const tabTitle = t(isShowingTabs ? 'toolbar.hideTabs' : 'toolbar.showTabs');

    const getDisabledShowHideButton = () =>
        isShowingTabs ? (
            <PredefinedIconUrl
                customIconUrl={tabsShownIconUrl?.disabled}
                disabled={true}
                uiLibIcon="LightBulbOutlinedIcon"
                size="small"
            />
        ) : (
            <PredefinedIconUrl
                customIconUrl={tabsHiddenIconUrl?.disabled}
                disabled={true}
                uiLibIcon="LightBulbFilledIcon"
                size="small"
            />
        );

    const getEnabledShowHideButton = () =>
        isShowingTabs ? (
            <PredefinedIconUrl
                customIconUrl={tabsShownIconUrl?.enabled}
                uiLibIcon="LightBulbOutlinedIcon"
                size="small"
            />
        ) : tabsShownIconUrl?.enabled ? (
            <PredefinedIconUrl
                customIconUrl={tabsHiddenIconUrl?.enabled}
                uiLibIcon="LightBulbFilledIcon"
                size="small"
            />
        ) : (
            <LightBulbFilledIcon />
        );

    const onClickShowHideButton = useCallback(async () => {
        await handleShowHideTabs({ ...currentOFIdentity, layoutName: activePage.layoutContainerKey });
        buttonRef.current?.focus();
    }, [activePage]);

    return (
        <BaseButton ref={buttonRef} title={tabTitle} disabled={pageIsLocked} onClick={onClickShowHideButton}>
            {pageIsLocked ? getDisabledShowHideButton() : getEnabledShowHideButton()}
        </BaseButton>
    );
};

const LightBulbFilledIcon = styled(Icon).attrs({
    icon: 'LightBulbFilledIcon',
    size: 'small',
    className: 'show-hide-tabs-lightbulb-icon'
})`
    svg path {
        color: var(--color-role-background-accent-base);
    }
`;

export default ShowHideTabsButton;
