import { useCallback, useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { OpenFin } from '@openfin/core';

import { updateBookmarkFavIcon } from '@common/utils/bookmarks';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import store from '@enterprise/store';

/**
 * This hook listens for favicon updates on the selected view and updates the bookmark favicon.
 */
export const useListenForFavIconUpdates = ({ url }: { url: string }) => {
    const { pageId } = useSelector(selectActivePage);
    const selectedViews = selectSelectedViewsForPage(store.getState(), pageId);
    const [selectedView, setSelectedView] = useState<OpenFin.View | null>(null);
    /**
     * This ref tracks the identity of the current view across renders.
     * It's necessary because the Redux selector (selectSelectedViewsForPage) returns
     * a new array reference on every state change, even when the actual view identity
     * hasn't changed. Using this ref prevents unnecessary removal and re-attachment
     * of event listeners when the component re-renders but the view hasn't actually
     * changed, improving performance and preventing potential memory leaks.
     */
    const viewIdentityRef = useRef<OpenFin.Identity>(null);

    /*
     * This handler is used to update the favicon of a bookmark after the view has loaded and favicons are updated.
     * This is necessary because the favicons are stale when url-changed event is fired,
     * this is a workaround to update the bookmark favicon to appropriate one.
     */
    const trailingFavIconUpdateHandler = useCallback(async () => {
        if (selectedView && url) {
            await updateBookmarkFavIcon(url, selectedView);
        }
    }, [url, selectedView]);

    useEffect(() => {
        const setupViewListener = async () => {
            if (!selectedViews.length || !url) {
                return;
            }
            if (selectedViews[0].name === viewIdentityRef.current?.name) {
                return;
            }

            if (selectedView) {
                await selectedView.removeListener('page-favicon-updated', trailingFavIconUpdateHandler);
            }

            const view = await fin.View.wrap(selectedViews[0]);
            viewIdentityRef.current = view.identity;
            setSelectedView(view);
            await view.addListener('page-favicon-updated', trailingFavIconUpdateHandler);
        };

        setupViewListener();

        return () => {
            (async () => {
                if (selectedView) {
                    await selectedView.removeListener('page-favicon-updated', trailingFavIconUpdateHandler);
                }
            })();
        };
    }, [selectedViews, url, trailingFavIconUpdateHandler, selectedView]);
};
