import type OpenFin from '@openfin/core';

import { createAsyncSubscription } from '@common/hooks/useAsyncSubscription';

export type ContextGroupChangedEvent = {
    identity: OpenFin.ClientIdentity;
    contextGroupId: string | null;
    previousContextGroupId: string | null;
};

/**
 * Subscribes to the Core 'client-changed-context-group' interop event.
 * Fires whenever any client in the broker changes its context group membership,
 * regardless of whether the change was initiated by workspace or by the view itself.
 */
export const useContextGroupChanged = createAsyncSubscription<(event: ContextGroupChangedEvent) => void>(
    'client-changed-context-group',
    (cb) => fin.me.interop.addListener('client-changed-context-group', cb),
    (cb) => fin.me.interop.removeListener('client-changed-context-group', cb)
);
