import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import { getCurrentOFWindow } from '@common/utils/window';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import {
    selectFirstViewIdForLayoutContainerKey,
    selectFirstViewNameForLayoutContainerKey
} from '@enterprise/slices/tab-focus';

import useSingleViewTitle from '@enterprise/components/ControlBar/Tablist/PageButton/useSingleViewTitle';

import { AttachedPage, WindowTitle } from '@client-platform/index';

export const getDocumentTitle = async (
    windowTitle: string | WindowTitle,
    activePage: AttachedPage,
    selectedView: OpenFin.Identity | null
) => {
    switch (typeof windowTitle) {
        case 'string': {
            console.warn(
                '[DEPRECATED] Type String has been deprecated for workspacePlatform.title. Please use the WindowTitle Type.'
            );
            return windowTitle;
        }
        case 'object': {
            switch (windowTitle.type) {
                case 'custom':
                    return windowTitle.value;
                case 'view-title': {
                    if (selectedView) {
                        const view = fin.View.wrapSync(selectedView);
                        const viewInfo = await view.getInfo();
                        return viewInfo.title;
                    } else {
                        return '';
                    }
                }
                case 'page-title': {
                    return activePage.title;
                }
                default:
                    return '';
            }
        }
        default:
            return '';
    }
};

export default function useWindowTitle() {
    const [windowTitle, setWindowTitle] = useState('');
    const [selectedView, setSelectedView] = useState<OpenFin.Identity | null>(null);
    const activePage = useSelector(selectActivePage);
    const viewName = useSelector(selectFirstViewNameForLayoutContainerKey(activePage.layoutContainerKey));
    const viewId = useSelector(selectFirstViewIdForLayoutContainerKey(activePage.layoutContainerKey));

    const enterpriseWindowTitle = useSingleViewTitle(activePage) + ' - Here';

    useEffect(() => {
        if (viewName && viewId) {
            setSelectedView({ name: viewName, uuid: viewId });
        } else {
            setSelectedView(null);
        }
    }, [viewName, viewId]);

    useEffect(() => {
        const updateWindowTitle = async () => {
            setWindowTitle(enterpriseWindowTitle);
        };

        const win = getCurrentOFWindow();

        // Event handler for changes in workspacePlatform title
        const handleWorkspacePlatformTitleChange = (payload: OpenFin.WindowEvents.WindowOptionsChangedEvent) => {
            if (!payload.diff.workspacePlatform) return;
            const { oldVal, newVal } = payload.diff.workspacePlatform;
            if (oldVal?.title?.type !== newVal?.title?.type) {
                updateWindowTitle();
            }
        };

        // Event handler for changes in the View URL
        const handleViewUrlChange = () => {
            updateWindowTitle();
        };

        // Initial update of document title
        updateWindowTitle();

        // Subscribe to changes in workspacePlatform title
        win.on('options-changed', handleWorkspacePlatformTitleChange);

        // Subscribe to updates in the page title
        win.on('view-page-title-updated', handleViewUrlChange);

        // Cleanup: remove event listeners and subscriptions
        return () => {
            win.removeListener('options-changed', handleWorkspacePlatformTitleChange);
            win.removeListener('view-page-title-updated', handleViewUrlChange);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activePage?.pageId, activePage?.title, selectedView?.name, enterpriseWindowTitle]);

    return windowTitle;
}
