import { FocusEventHandler, MutableRefObject, useCallback, useContext } from 'react';

import isEmpty from 'lodash.isempty';

import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { WindowSearchMenuContext } from '@enterprise/context/SearchMenu/WindowSearchMenuContext';

/**
 * Custom hook that returns action handlers for the address input DOM element that update the search view expansion state.
 *
 * @param {MutableRefObject<HTMLInputElement>} addressBarInputRef - Ref object pointing to the address input element.
 * @param {React.Dispatch<React.SetStateAction<string>>} setSearchText - Function that updates the search text.
 * @param {React.Dispatch<React.SetStateAction<boolean>>} setInputFocus - Function that updates the input focus state.
 * @param {() => void} resetAddressBarToSelectedViewUrl - Function to reset the address bar with the selected view's URL.
 *
 * @returns Object containing functions to handle input change, click, and blur events.
 */
export const useUpdateInputExpansionState = (
    addressBarInputRef: MutableRefObject<HTMLInputElement>,
    setSearchText: React.Dispatch<React.SetStateAction<string>>,
    setInputFocus: React.Dispatch<React.SetStateAction<boolean>>,
    resetAddressBarToSelectedViewUrl: () => void
) => {
    const { shouldExpandMenu, setShouldExpandMenu } = useContext(WindowSearchMenuContext);

    const onChange: React.ChangeEventHandler<HTMLInputElement> = useCallback((event) => {
        if (isEmpty(event.target.value)) {
            raiseBrowserAnalytics({
                action: 'Clear Search',
                type: 'Search'
            });
        }
        setShouldExpandMenu({ shouldExpand: true, method: 'keystroke' });
        setSearchText(event.target.value);
    }, []);

    const onClick: React.MouseEventHandler<HTMLInputElement> = useCallback(() => {
        if (!shouldExpandMenu.shouldExpand) {
            setShouldExpandMenu({ shouldExpand: true, method: 'click' });
        }
    }, [shouldExpandMenu.shouldExpand]);

    const onBlur: FocusEventHandler<HTMLInputElement> = useCallback(() => {
        setInputFocus(false);

        if (document.activeElement !== addressBarInputRef.current) {
            raiseBrowserAnalytics({
                action: 'Blur Search',
                type: 'Search'
            });
            setShouldExpandMenu({ shouldExpand: false });
            resetAddressBarToSelectedViewUrl();
        }
    }, [addressBarInputRef, resetAddressBarToSelectedViewUrl]);

    return { onChange, onClick, onBlur };
};
