import React, { PropsWithChildren, useCallback } from 'react';

import type OpenFin from '@openfin/core';

import { BaseCustomButtonStyleProps } from '@common/utils/base-button-props';
import { currentOFIdentity } from '@common/utils/window';

import { getCurrentSync, wrapSync } from '@client-platform/api';
import { CustomActionCallerType, CustomButtonActionPayload } from '@client-platform/shapes';

import { CustomButtonConfig } from '../../api/action';

import BaseCustomButton from './BaseCustomButton';

interface Props extends CustomButtonConfig {
    customTarget?: OpenFin.Identity;
    analyticsCallback?: (action: CustomButtonConfig['action']) => any;
    dragging?: boolean;
    onContextMenu?: (event: React.MouseEvent) => void;
    toolbarIconButton?: boolean;
}

/**
 * A button that dispatches custom actions to the platform
 */
export const CustomButton: React.FC<
    PropsWithChildren<Props & BaseCustomButtonStyleProps & Exclude<Parameters<typeof BaseCustomButton>[0], 'childern'>>
> = ({ action, customTarget, children, analyticsCallback, dragging, toolbarIconButton, ...props }) => {
    const callback = useCallback(
        async (event: React.MouseEvent) => {
            if (dragging) {
                return;
            }
            const payload: CustomButtonActionPayload = {
                windowIdentity: currentOFIdentity,
                x: event.clientX,
                y: event.clientY,
                customData: action.customData,
                callerType: CustomActionCallerType.CustomButton
            };

            if (analyticsCallback) {
                analyticsCallback(action);
            }

            const target = customTarget ? wrapSync(customTarget) : getCurrentSync();
            // eslint-disable-next-line no-underscore-dangle
            return target._invokeCustomAction(action.id, payload);
        },
        [action, customTarget, analyticsCallback, dragging]
    );

    return (
        <BaseCustomButton {...props} toolbarIconButton={toolbarIconButton} onClick={callback}>
            {children}
        </BaseCustomButton>
    );
};
