import type OpenFin from '@openfin/core';

import { isFin } from '@common/utils/env';
import { getNewLandingTabViewOptions } from '@common/utils/landing-page';

import { getCurrentSync } from '@client-platform/api';

export function getOFView(identity: OpenFin.Identity) {
    if (!isFin) {
        throw new Error(
            'getOFView can only be used in an OpenFin env. Avoid calling this method during pre-rendering.'
        );
    }
    return fin.View.wrapSync(identity);
}

/**
 * Creates a new View to the landing page at the end of the tab strip
 * which includes the currently selected View
 * @param view the currently selected View
 */
export const makeNewView = async (view: OpenFin.View) => {
    const windowIdentity = fin.Window.getCurrentSync().identity;
    const viewOptions = await getNewLandingTabViewOptions(windowIdentity);
    await getCurrentSync().createView(viewOptions, windowIdentity, view.identity);
};

/**
 * Duplicates the current View at the end of the tab strip
 * which includes the currently selected View
 * @param view the currently selected View
 */
export const duplicateView = async (view: OpenFin.View) => {
    const windowIdentity = fin.Window.getCurrentSync().identity;
    // need to get url separately because it's not updated in options
    const { url } = await view.getInfo();
    const sourceViewOpts = await view.getOptions();
    const viewOptions = {
        ...sourceViewOpts,
        url,
        target: windowIdentity,
        name: undefined
    } as OpenFin.PlatformViewCreationOptions;
    await getCurrentSync().createView(viewOptions, windowIdentity, view.identity);
};
