import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import debounce from 'lodash.debounce';

import { decodeDragPayload, getDragPayloadType, isSingleViewDrag } from '@common/utils/page-drag';
import { currentOFIdentity } from '@common/utils/window';

import { AttachedPageInternal } from '@common/api/pages/shapes';

import { getCurrentSync } from '@client-platform/index';

/**
 * Manages an dragging items within, out of, and into a list of pages. Uses dragover event to determine position of drop indicator.
 */
export const usePageDrag = (pages: AttachedPageInternal[]) => {
    const [dropIndicatorPosition, setIndicatorPosition] = useState(null);
    const [hoveredPageIndex, setHoveredPageIndex] = useState(null);
    const [isShowingDropIndicator, setShowingDropIndicatorState] = useState(false);
    const isShowingDropIndicatorRef = useRef(false);
    const mouseCoordRef = useRef({ x: 0, y: 0 });
    const hasSetActivePageRef = useRef(false);

    const setIsShowingDropIndicator = useCallback((value: boolean) => {
        isShowingDropIndicatorRef.current = value;
        setShowingDropIndicatorState(value);
    }, []);

    const setActivePageHelper = useCallback(
        async (pageId: string) => {
            hasSetActivePageRef.current = true;
            await getCurrentSync()
                .Browser.wrapSync(currentOFIdentity)
                .setActivePage(pageId)
                .finally(() => {
                    hasSetActivePageRef.current = false;
                });
        },
        [hasSetActivePageRef]
    );

    // leading debounced function ensures we don't repeatedly call setActivePage during drag
    const debouncedSetActivePage = useMemo(
        () => debounce(setActivePageHelper, 500, { leading: true, trailing: false }),
        [setActivePageHelper]
    );

    const onPageDragOver = useCallback(
        async (e: React.DragEvent<HTMLDivElement>, { pageId, isActive }: AttachedPageInternal) => {
            const pageDropType = e.dataTransfer.types.find((type) => type.startsWith(getDragPayloadType(true)));
            // we don't want to show indicator for some reason (e.g. unsupported drag)
            // Use ref so the first dragover after dragenter sees the updated value before re-render (avoids indicator flash)
            if (!isShowingDropIndicatorRef.current) {
                return;
            }

            const pageButtonBoundingRect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
            const mouseX = e.pageX;
            const mouseY = e.pageY;

            const targetPageIndex = pages.findIndex((page) => page.pageId === pageId);
            const pageElement = e.currentTarget;

            const isWithinActivationBounds = (x: number, y: number, areaRect: DOMRect) => {
                const pageX30pct = areaRect.left + areaRect.width * 0.3;
                const pageX70pct = areaRect.left + areaRect.width * 0.7;
                return x > pageX30pct && x < pageX70pct && y > areaRect.top && y < areaRect.bottom;
            };
            const isViewDrag = isSingleViewDrag(e);
            if (isViewDrag && isWithinActivationBounds(mouseX, mouseY, pageButtonBoundingRect)) {
                const viewDropType = e.dataTransfer.types.find((type) => type.startsWith('payload'));
                const viewDragMetadata = viewDropType ? decodeDragPayload(viewDropType) : null;
                /** There is a Container bug where tab drag
                 * from one layout into another in the same window doesn't work.
                 * This restricts that scenario until the bug is fixed.
                 * Container bug: https://openfin.jira.com/browse/CORE-1895 */
                const shouldActivatePage =
                    viewDragMetadata?.sourceIdentity?.name !== currentOFIdentity.name || pageDropType;

                setTimeout(async () => {
                    const currentPageRect = pageElement?.getBoundingClientRect();
                    // check if we are still within activation bounds of the page tab
                    if (
                        currentPageRect &&
                        isWithinActivationBounds(mouseCoordRef.current.x, mouseCoordRef.current.y, currentPageRect)
                    ) {
                        setIndicatorPosition(null);
                        setHoveredPageIndex(targetPageIndex);

                        if (!isActive && shouldActivatePage && !hasSetActivePageRef.current) {
                            debouncedSetActivePage(pageId);
                        }
                        mouseCoordRef.current = { x: 0, y: 0 };
                    }
                }, 500);

                return;
            } else {
                setHoveredPageIndex(null);
                // Get horizontal middle
                const pageMiddleX = (pageButtonBoundingRect.left + pageButtonBoundingRect.right) / 2;
                // Only perform the move when the mouse has crossed half of the page tab's width
                if (dropIndicatorPosition !== targetPageIndex && mouseX < pageMiddleX) {
                    // show drop indicator before hovered page
                    setIndicatorPosition(targetPageIndex);
                } else if (dropIndicatorPosition !== targetPageIndex + 1 && mouseX > pageMiddleX) {
                    // show drop indicator after hovered page
                    setIndicatorPosition(targetPageIndex + 1);
                }
            }
        },
        [pages, dropIndicatorPosition, debouncedSetActivePage, hasSetActivePageRef]
    );
    useEffect(() => {
        const dragOverListener = (event: DragEvent) => {
            mouseCoordRef.current = { x: event.clientX, y: event.clientY };
        };
        document.addEventListener('dragover', dragOverListener, { capture: true });

        return () => document.removeEventListener('dragover', dragOverListener, { capture: true });
    }, []);

    return {
        onPageDragOver,
        dropIndicatorPosition,
        isShowingDropIndicator,
        setIsShowingDropIndicator,
        hoveredPageIndex
    };
};
