import { useCallback, useEffect } from 'react';

import { OpenFin } from '@openfin/core';

import { handleEscapeHotkey } from '@common/utils/hotkeys';

import { useIsWindows } from './useIsWindows';

interface UseSetUpViewEscapeHotkeysProps {
    selectedView?: OpenFin.View;
}

/**
 * This hook is used to set up the hotkey for escaping focus from a view to the window.
 * @param selectedView - The view to set up the hotkey for.
 * @returns void
 */
export const useSetUpViewEscapeHotkeys = ({ selectedView }: UseSetUpViewEscapeHotkeysProps) => {
    const isWindows = useIsWindows();

    const handleViewHotkey = useCallback(
        async (e: OpenFin.Events.ViewEvents.HotkeyEvent) => {
            await handleEscapeHotkey(e, isWindows);
        },
        [isWindows]
    );

    useEffect(() => {
        if (selectedView) {
            selectedView.addListener('hotkey', handleViewHotkey);
        }
        return () => {
            if (selectedView) {
                selectedView.removeListener('hotkey', handleViewHotkey);
            }
        };
    }, [selectedView, handleViewHotkey]);
};
