import { useEffect, useRef } from 'react';

import type OpenFin from '@openfin/core';

import { focusManager } from '../services/focus-manager';
import { FOCUS_PRIORITY } from '../types/focus';
import { blurAddressBar, handleAddressBarFocusForLandingPage } from '../utils/address-bar-focus';
import { createInlineDebugLogger } from '../utils/debug-log';

export interface UseViewFocusCoordinationProps {
    /** The currently active page */
    activePage: { pageId: string } | undefined;
    /** The focused view in the active page, if any */
    focusedViewInActivePage: OpenFin.Identity | undefined;
    /** Function to check if a modal is open */
    isModalOpen?: boolean;
    /** Whether this is enterprise mode (has address bar) */
    isEnterprise?: boolean;
    /** Whether the active page is currently transitioning (e.g. during page close/switch) */
    isActivePageChanging?: boolean;
}

/**
 * Coordinates focus between views and the address bar using the centralized FocusManager.
 *
 * This hook manages focus in a simplified way:
 * 1. When a view/page changes, focus the view (unless modal is open)
 * 2. Handle address bar focus for landing pages (enterprise only)
 * 3. Scroll the active page tab into view
 * ```
 */
const debug = createInlineDebugLogger('useViewFocusCoordination');

export const useViewFocusCoordination = ({
    activePage,
    focusedViewInActivePage,
    isModalOpen = false,
    isEnterprise = false,
    isActivePageChanging = false
}: UseViewFocusCoordinationProps): void => {
    const prevPageIdRef = useRef<string | null>(null);
    const prevViewNameRef = useRef<string | null>(null);
    const prevModalOpenRef = useRef<boolean>(false);
    const lastFocusedViewRef = useRef<string | null>(null);

    useEffect(() => {
        if (!activePage) return;

        const pageChanged = prevPageIdRef.current !== activePage.pageId;
        const viewChanged = prevViewNameRef.current !== focusedViewInActivePage?.name;
        const modalClosed = prevModalOpenRef.current === true && isModalOpen === false;

        debug('effect triggered', {
            pageId: activePage.pageId,
            viewName: focusedViewInActivePage?.name,
            pageChanged,
            viewChanged,
            modalClosed,
            isModalOpen,
            isActivePageChanging
        });

        prevPageIdRef.current = activePage.pageId;
        prevViewNameRef.current = focusedViewInActivePage?.name || null;
        prevModalOpenRef.current = isModalOpen;

        // When page changes, clear the last focused view tracking
        if (pageChanged) {
            lastFocusedViewRef.current = null;
        }

        // Scroll the active page tab into view
        document.getElementById(activePage.pageId)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

        if (focusedViewInActivePage) {
            // If modal is open, focus manager will block the focus request
            if (isModalOpen) {
                return;
            }

            // Only apply focus changes if something relevant changed:
            // - Page changed
            // - View changed
            // - Modal just closed (need to restore focus to view)
            // This prevents unnecessary focus changes when right-clicking tabs (which activates the page but doesn't change the view)
            if (!pageChanged && !viewChanged && !modalClosed) {
                return;
            }

            // When a modal closes during a page close/switch, the view on the current page is
            // about to be destroyed. Skip the focus request and let the upcoming pageChanged/viewChanged
            // triggers handle focus once the transition settles.
            if (modalClosed && !pageChanged && !viewChanged && isActivePageChanging) {
                debug('skipping modalClosed focus: active page is transitioning');
                return;
            }

            // Capture the view identity to avoid stale closures
            const viewIdentity = focusedViewInActivePage;
            const isFirstFocusOnThisView = lastFocusedViewRef.current !== viewIdentity.name;

            // Request focus on the view first (so something is focused immediately)
            focusManager.requestFocus({
                target: { type: 'view', identity: viewIdentity },
                priority: FOCUS_PRIORITY.VIEW,
                source: 'programmatic'
            });

            // Address bar logic only applies to enterprise (non-enterprise has no address bar)
            if (isEnterprise) {
                // Only focus the address bar on the first focus of a landing page
                // On subsequent focuses, blur the address bar to keep focus on the view for accessibility
                if (isFirstFocusOnThisView) {
                    // Then check if we should focus the address bar for landing pages
                    handleAddressBarFocusForLandingPage(viewIdentity, () => isModalOpen);
                } else {
                    // On subsequent focuses of the same view, blur the address bar
                    // This ensures focus stays on the view (e.g., for tabbing through landing page content)
                    blurAddressBar();
                }
            }

            // Update the last focused view
            lastFocusedViewRef.current = viewIdentity.name;
        } else {
            // Clear focus when no view is focused (e.g. view torn out to new window)
            focusManager.clearFocus();
        }
    }, [activePage, focusedViewInActivePage, isEnterprise, isModalOpen, isActivePageChanging]);
};
