import * as base32 from 'hi-base32';

import * as namespacedLocalStorage from '@common/utils/namespaced-local-storage';

import { AttachedPage } from '@client-platform/shapes';

import LocalStorageKey from './local-storage-key';
import { currentOFIdentity } from './window';
/**
 * Determines if a given DragEvent is within the bounds of a specified parent element.
 *
 * @param {DragEvent} event - The DragEvent to check.
 * @param {DOMRect} parentBounds - The bounding rectangle of the parent element.
 * @returns {boolean} true if the event is within the parent bounds, false otherwise.
 */
export const isWithinParentBounds = (event: DragEvent, parentBounds: DOMRect) => {
    return (
        event.pageX >= parentBounds.left &&
        event.pageX <= parentBounds.right &&
        event.pageY >= parentBounds.top &&
        event.pageY <= parentBounds.bottom
    );
};

/** Determines the action to be taken once page is dropped */
type DragState = 'reorder' | 'reparent' | 'popout' | null;

export const getDragState = (): DragState => {
    return namespacedLocalStorage.getItem(LocalStorageKey.PageDragState) as DragState;
};

export const setDragState = (value: DragState) => {
    if (value !== null) {
        namespacedLocalStorage.setItem(LocalStorageKey.PageDragState, value);
    } else {
        namespacedLocalStorage.removeItem(LocalStorageKey.PageDragState);
    }
};

export const hideSingleView = async () => {
    const views = await fin.Platform.Layout.getCurrentSync().getCurrentViews();
    if (views.length === 1) {
        fin.View.wrapSync(views[0].identity).hide();
    }
};

export const getViewTabPayload = (event: React.DragEvent) => {
    const payload = event.dataTransfer.getData('view-identity');
    if (!payload) return null;
    const infoArray = JSON.parse(payload);
    const viewOptions = JSON.parse(infoArray[0]);
    return viewOptions;
};

export const isSingleViewDrag = (event: React.DragEvent) => {
    return event.dataTransfer.types.some((type) => type.startsWith('view-identity'));
};

/**
 * Returns an array of pages where page corresponding to currentDragPageId is moved to index targetPositionIndex.
 */
export function getReorderedPages(pages: AttachedPage[], currentDragPageId: string, targetPositionIndex: number) {
    return pages.flatMap((page, index) => {
        const subarray = page.pageId === currentDragPageId ? [] : [page.pageId];
        if (index === targetPositionIndex) {
            subarray.unshift(currentDragPageId);
        } else if (index === pages.length - 1 && targetPositionIndex === index + 1) {
            subarray.push(currentDragPageId);
        }
        return subarray;
    });
}

/**
 * Our custom drag and drop data transfer type.
 * This is used to determine that it is a page being dropped on our window, and not anything else.
 *
 * Note: This must be lowercase! DnD eventing will automatically lowercase it in flight.
 */
export const getDragPayloadType = (isEnterprise?: boolean) =>
    base32.encode(`fin${isEnterprise ? '/enterprise' : ''}/page/uuid:${currentOFIdentity.uuid}`).toLowerCase();

type TabDragPayload = {
    sourceIdentity: {
        uuid: string;
        name: string;
    };
    settings: {
        preventDragOut: boolean;
    };
};
export const decodeDragPayload = (payload: string): TabDragPayload => {
    const tabDragData = payload.replace('payload:', '').toUpperCase();
    return JSON.parse(base32.decode(tabDragData));
};

export const encodeDragPayload = (payload: TabDragPayload): string => {
    return `payload:${base32.encode(JSON.stringify(payload))}`;
};
