const NavForward = (): JSX.Element => {
    const [canGoForward, setCanGoForward] = useState<boolean>(false);
    const focusedView = useFocusedView();

    const goforward = async () => {
        if (focusedView) {
            focusedView.view.navigateForward();
        }
    };

    useEffect(() => {
        const checkNav = async () => {
            if (focusedView) {
                setCanGoForward(focusedView.info.canNavigateForward);
            } else {
                setCanGoForward(false);
            }
        };
        checkNav();
    }, [focusedView]);

    return (
        <NavigateButton
            title="Click to go forward"
            onClick={goforward}
            data-testid={enterpriseNavigationTestIds.forwardButton}
            disabled={!canGoForward}
        >
            <NavigateForwardIcon />
        </NavigateButton>
    );
};

const NavReloadStop: React.FC = () => {
    const focusedView = useFocusedView();
    const { isContentLoading, setIsContentLoading } = useFocusedViewListeners(focusedView);

    const reload = async () => {
        if (focusedView) {
            setIsContentLoading(true);
            focusedView.view.reload();
        }
    };

    const stop = async () => {
        if (focusedView) {
            focusedView.view.stopNavigation();
            setIsContentLoading(false);
        }
    };

    return isContentLoading ? (
        <NavigateButton
            title="Stop loading this tab"
            onClick={stop}
            data-testid={enterpriseNavigationTestIds.stopButton}
        >
            <NavigateStopIcon />
        </NavigateButton>
    ) : (
        <NavigateButton title="Reload this tab" onClick={reload} data-testid={enterpriseNavigationTestIds.reloadButton}>
            <NavigateReloadIcon />
        </NavigateButton>
    );
};

