import { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';

import { OpenFin } from '@openfin/core';

import { isLandingPage } from '@common/utils/enterpriseBrowser';
import { countViews } from '@common/utils/layout';

import type { AttachedPageInternal } from '@common/api/pages/shapes';

import { type AttachedPagesRootState, selectActivePage, selectPage } from '@enterprise/slices/pages/attached';

const isPageSingleView = (page?: AttachedPageInternal): boolean => {
    if (page?.layout?.content) {
        return countViews(page?.layout?.content) === 1;
    }
    return false;
};

export const useIsPageSingleView = (pageId: string): boolean => {
    const page = useSelector<AttachedPagesRootState, AttachedPageInternal>((state) => selectPage(state, pageId));
    return useMemo(() => isPageSingleView(page), [page]);
};

export const useIsActivePageSingleView = (): boolean => {
    const activePage = useSelector(selectActivePage);
    return useMemo(() => isPageSingleView(activePage), [activePage]);
};

/**
 * This hook returns true if the active page is a single view on the landing page or if its multi view page.
 * This is used to determine if the bottom border of the page button should be shown.
 * @param page: AttachedPageInternal
 * @returns boolean
 */
export const useIsSingleViewLandingPageOrMultiViewPage = (page: AttachedPageInternal): boolean => {
    // Default set to true to hide the bottom border and mitigate the bottom border flashing
    const [shouldHideBottomBorder, setShouldHideBottomBorder] = useState(true);
    const [view, setView] = useState<OpenFin.View>();

    const checkIsLandingFromUrlChangedEvent = (e: OpenFin.Events.WebContentsEvents.UrlChangedEvent) => {
        setShouldHideBottomBorder(isLandingPage(e.url));
    };

    const checkIsLandingFromUrl = (url: string) => {
        setShouldHideBottomBorder(isLandingPage(url));
    };

    useEffect(() => {
        if (page?.singleViewName) {
            (async () => {
                const v = fin.View.wrapSync({ uuid: fin.me.uuid, name: page.singleViewName });
                setView(v);
                v.on('url-changed', checkIsLandingFromUrlChangedEvent);
                const url = (await v.getInfo()).url;
                checkIsLandingFromUrl(url);
            })();
        } else if (view) {
            // when not single view: clean up listener, to prevent memory leak, and reset state
            view.removeListener('url-changed', checkIsLandingFromUrlChangedEvent);
            setView(undefined);
            setShouldHideBottomBorder(true);
        }
        return () => {
            if (view) {
                view.removeListener('url-changed', checkIsLandingFromUrlChangedEvent);
            }
        };
    }, [page?.singleViewName]);

    return shouldHideBottomBorder;
};
