import { useContext, useEffect } from 'react';

import { enterpriseNavigationTestIds } from '@common/utils/test-ids';

import BookmarkFilledSvg from '@enterprise/assets/icons/bookmark-filled.svg';
import BookmarkOutlinedSvg from '@enterprise/assets/icons/bookmark-outline.svg';

import useSystemSchemeCheck from '@common/hooks/useSystemSchemeCheck';
import { BookmarksContext } from '@enterprise/context/BookmarksContext';
import { useIsBookmarked } from '@enterprise/hooks/EnterpriseSearchMenu/useIsBookmarked';
import { useIsSelectedViewNavigated } from '@enterprise/hooks/EnterpriseSearchMenu/useIsSelectedViewNavigated';
import { useListenForFavIconUpdates } from '@enterprise/hooks/EnterpriseSearchMenu/useListenForFavIconUpdates';
import { useAddEditBookmarkDialog } from '@enterprise/hooks/useAddEditBookmarkDialog';

import { IconContainer } from './IconContainer';

type BookmarkIconProps = {
    url?: string;
    isSecureShowing?: boolean;
    bookmarkButtonRef: React.MutableRefObject<HTMLDivElement>;
    onRenderChange?: (isRendered: boolean) => void;
    isMenuExpanded?: boolean;
};

export const BookmarkButton = ({
    url,
    isSecureShowing,
    bookmarkButtonRef,
    onRenderChange,
    isMenuExpanded
}: BookmarkIconProps) => {
    const { isSchemeDark } = useSystemSchemeCheck();
    useListenForFavIconUpdates({ url });
    const { selectedView, isViewNavigatedToUrl } = useIsSelectedViewNavigated({ url });
    const { showDialog, isDialogShown, isBookmarkUpdatedOrCreated } = useAddEditBookmarkDialog(
        bookmarkButtonRef,
        selectedView
    );

    const { mostRecentlyUpdated } = useContext(BookmarksContext);
    const isBookmarked = useIsBookmarked(url, isBookmarkUpdatedOrCreated, mostRecentlyUpdated);
    const shouldRender = isViewNavigatedToUrl && isSecureShowing && !isMenuExpanded;

    useEffect(() => {
        onRenderChange?.(shouldRender);
    }, [shouldRender, onRenderChange]);

    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            showDialog();
        }
    };

    return (
        shouldRender && (
            <IconContainer
                isSchemeDark={isSchemeDark}
                onClick={showDialog}
                onKeyDown={handleKeyDown}
                isDialogShown={isDialogShown}
                ref={bookmarkButtonRef}
                shouldRender={shouldRender}
                tabIndex={0}
                role="button"
                aria-label="Add or edit bookmark"
                data-testid={enterpriseNavigationTestIds.bookmarkButton}
            >
                {isBookmarked ? <BookmarkFilledSvg /> : <BookmarkOutlinedSvg />}
            </IconContainer>
        )
    );
};
