import { AriaAttributes, AriaRole } from 'react';

// eslint-disable-next-line @typescript-eslint/no-namespace
namespace ScreenReaderAnnouncement {
    export interface Props {
        message: string;
        ariaAttributes?: AriaAttributes;
        ariaRole?: AriaRole;
    }
}

/**
 * A hidden component that announces screen reader messages to the user.
 *
 * Props:
 * - message: The message to announce to the user.
 * - ariaAttributes: Additional aria attributes to apply to the component. Default attributes are { aria-live: 'polite', aria-atomic: 'true' }
 * - ariaRole: The role to apply to the component. Defaults to 'status'.
 */
export const ScreenReaderAnnouncement = ({ message, ariaAttributes, ariaRole }: ScreenReaderAnnouncement.Props) => {
    return (
        <div
            aria-live="polite"
            aria-atomic="true"
            role={ariaRole || 'status'}
            tabIndex={-1}
            style={{
                clip: 'rect(0 0 0 0)',
                clipPath: 'inset(50%)',
                height: '1px',
                overflow: 'hidden',
                position: 'absolute',
                whiteSpace: 'nowrap',
                width: '1px'
            }}
            {...ariaAttributes}
        >
            {message}
        </div>
    );
};
