import { useEffect, useState } from 'react';

import { AttachedPageInternal } from '@common/api/pages/shapes';

const useSingleViewTitle = (page: AttachedPageInternal) => {
    const [singleViewTitle, setSingleViewTitle] = useState<string>('');

    useEffect(() => {
        if (page.singleViewName) {
            const finView = fin.View.wrapSync({ uuid: fin.me.uuid, name: page.singleViewName });
            const onPageTitleUpdated = (event: { title: string }) => {
                setSingleViewTitle(event.title);
            };
            finView.on('page-title-updated', onPageTitleUpdated);
            finView.getInfo().then(({ title }) => setSingleViewTitle(title));
            return () => {
                finView.removeListener('page-title-updated', onPageTitleUpdated);
            };
        } else {
            setSingleViewTitle(null);
        }
    }, [page.layoutContainerKey, page.singleViewName]);

    if (!(page as AttachedPageInternal).attachedPageType) {
        // if page type does not exist yet, return empty string
        return '';
    }

    return page.singleViewName ? singleViewTitle : page.title;
};

export default useSingleViewTitle;
