import React, { useMemo } from 'react';

import type { ToolbarOptions } from '@client-platform/shapes';

import { useWindowOptions } from '@common/hooks/useWindowOptions';
import { RightControlsButton } from '../RightControlsButton/RightControlsButton';
import { defaultToolbarButtonConfig } from '../utils';

const getToolbarButtonOptions = (toolbarOptions?: ToolbarOptions): ToolbarOptions => {
    return toolbarOptions && typeof toolbarOptions === 'object' && toolbarOptions.buttons
        ? toolbarOptions
        : defaultToolbarButtonConfig;
};

/**
 * Top level container component for Browsers Icons.
 */
const ToolbarContainer: React.FC = () => {
    const { workspacePlatform } = useWindowOptions();

    const toolbarButtonConfig = useMemo(() => {
        const buttonOptions = getToolbarButtonOptions(workspacePlatform?.toolbarOptions);
        return buttonOptions.buttons;
    }, [workspacePlatform?.toolbarOptions]);

    return (
        <>
            {toolbarButtonConfig.map((config, index) => {
                return <RightControlsButton {...config} key={index} />;
            })}
        </>
    );
};

export default ToolbarContainer;
