import type OpenFin from '@openfin/core';

import { getPrintOption, MenuItemType, Separator } from '@common/utils/context-menu';
import { checkHasNewTabUrl } from '@common/utils/landing-page';

import { t } from '@common/api/i18next';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import { getCurrentSync, ViewTabContextMenuTemplate } from '@client-platform/index';
import { ViewTabMenuData, ViewTabMenuOptionType } from '@client-platform/shapes';

import store from '../../store';

let currentViewsIdentities: OpenFin.Identity[] = [];

const getNewViewOption = async (enabled: boolean): Promise<ViewTabContextMenuTemplate> => ({
    type: MenuItemType.Label,
    label: t('enterpriseContextMenu.newTab'),
    data: { type: ViewTabMenuOptionType.NewView } as ViewTabMenuData,
    enabled
});

const getReloadViewsOption = async (): Promise<ViewTabContextMenuTemplate> => ({
    type: MenuItemType.Label,
    label: t('contextMenu.reload'),
    data: { type: ViewTabMenuOptionType.ReloadViews } as ViewTabMenuData
});

const getDuplicateViewsOption = async (enabled: boolean): Promise<ViewTabContextMenuTemplate> => ({
    type: MenuItemType.Label,
    label: t('contextMenu.duplicate'),
    data: { type: ViewTabMenuOptionType.DuplicateViews } as ViewTabMenuData,
    enabled
});

const getCloseViewsOption = async (selectedViewIdentities: OpenFin.Identity[]): Promise<ViewTabContextMenuTemplate> => {
    const optsForSelectedViews = await Promise.all(
        selectedViewIdentities.map((viewIdentity) => fin.View.wrapSync(viewIdentity).getOptions())
    );
    const parentWin = await fin.View.wrapSync(selectedViewIdentities[0]).getCurrentWindow();
    const activePage = (await getCurrentSync().Browser.wrapSync(parentWin.identity).getPages()).find(
        (page) => page.isActive
    );

    const canCloseAllSelectedViews =
        !optsForSelectedViews.some((viewOpts) => !viewOpts.isClosable) && !activePage.isLocked;
    return {
        type: MenuItemType.Label,
        label: t('contextMenu.closeTab'),
        enabled: canCloseAllSelectedViews,
        data: { type: ViewTabMenuOptionType.CloseViews } as ViewTabMenuData
    };
};

export async function getMenuTemplate(): Promise<ViewTabContextMenuTemplate[]> {
    const activePage = selectActivePage(store.getState());
    currentViewsIdentities = selectSelectedViewsForPage(store.getState(), activePage.pageId);
    const isPageUnlocked = !activePage.isLocked;
    const hasNewTabUrl = await checkHasNewTabUrl();

    return [
        ...(hasNewTabUrl ? [await getNewViewOption(isPageUnlocked)] : []),
        // TODO: remove cast once @openfin/core updates their types
        Separator as ViewTabContextMenuTemplate,
        await getReloadViewsOption(),
        await getDuplicateViewsOption(isPageUnlocked),
        (await getPrintOption()) as ViewTabContextMenuTemplate,
        // TODO: remove cast once @openfin/core updates their types
        Separator as ViewTabContextMenuTemplate,
        await getCloseViewsOption(currentViewsIdentities)
    ];
}
