import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

import OpenFin from '@openfin/core';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { selectLayoutsWithSelectedViews } from '@enterprise/slices/tab-focus';

import {
    getViewWithInfo,
    ViewInfo
} from '@enterprise/components/ControlBar/LeftControlsContainer/EnterpriseNavigationContainer/EnterpriseNavigationContainer';

const useFocusedView = () => {
    const activePage = useSelector(selectActivePage);
    const layoutsWithSelectedViews = useSelector(selectLayoutsWithSelectedViews);
    const selectedViewsIdentities = layoutsWithSelectedViews[activePage.layoutContainerKey];
    const [viewInfo, setViewInfo] = useState<ViewInfo | null>();

    useEffect(() => {
        if (selectedViewsIdentities?.length === 1) {
            getViewWithInfo(selectedViewsIdentities[0]).then(({ view, info }) => setViewInfo({ view, info }));
        } else {
            setViewInfo(null);
        }
    }, [selectedViewsIdentities]);

    useEffect(() => {
        const win = fin.Window.getCurrentSync();
        const urlChangedListener: OpenFin.BaseEvents.EventHandler<
            OpenFin.Events.WindowEvents.WindowEvent,
            'view-url-changed'
        > = async ({ viewIdentity }) => {
            if (
                selectedViewsIdentities &&
                selectedViewsIdentities.length > 0 &&
                selectedViewsIdentities[0].name === viewIdentity.name
            ) {
                const updates = await getViewWithInfo(viewIdentity);
                setViewInfo(updates);
            }
        };
        win.addListener('view-url-changed', urlChangedListener);

        return () => {
            win.removeListener('view-url-changed', urlChangedListener);
        };
    }, [selectedViewsIdentities]);

    return viewInfo;
};

export default useFocusedView;
