import { useEffect } from 'react';

import OpenFin from '@openfin/core';

import { dispatch, getState } from '@enterprise/api/pages/state';
import { selectPages, updatePageAtIndex } from '@enterprise/slices/pages/attached';

/**
 * This hook is used to update the supertab icons for single view supertabs. It utilizes the window event 'view-page-favicon-updated'
 * to listen for favicon updates and update the icon in the corresponding supertab.
 */
export const usePageIcon = () => {
    useEffect(() => {
        const finWindow = fin.Window.getCurrentSync();

        const updatePageIcon = (event: OpenFin.WindowEvents.ByType<'view-page-favicon-updated'>) => {
            const pages = selectPages(getState());
            const matchIndex = pages.findIndex((page) => page?.singleViewName === event.viewIdentity.name);
            if (matchIndex !== -1) {
                const updatedPage = pages[matchIndex];
                const newIcon = event.favicons[0];
                console.debug('Updating Page Icon for:', { pageId: updatedPage.pageId, newIcon });
                dispatch(
                    updatePageAtIndex({
                        index: matchIndex,
                        page: { ...updatedPage, pageIcon: newIcon }
                    })
                );
            }
        };

        finWindow.addListener('view-page-favicon-updated', updatePageIcon);

        return () => {
            finWindow.removeListener('view-page-favicon-updated', updatePageIcon);
        };
    }, []);
};
