import type OpenFin from '@openfin/core';

import { getIsEnterprisePlatform } from '../enterprise';

export const KEYBOARD_COMMANDS = {
    NEW_TAB: 'workspace.newTab',
    FIND_IN_PAGE: 'findInPage.show'
} as const;

const WORKSPACE_DEFAULT_COMMANDS: OpenFin.ShortcutOverride[] = [
    { command: KEYBOARD_COMMANDS.NEW_TAB, keys: 'CommandOrControl+T' },
    { command: KEYBOARD_COMMANDS.FIND_IN_PAGE, keys: 'CommandOrControl+F', phase: 'bubble' }
];
const ENTERPRISE_DEFAULT_COMMANDS: OpenFin.ShortcutOverride[] = [
    { command: KEYBOARD_COMMANDS.FIND_IN_PAGE, keys: 'CommandOrControl+F', phase: 'bubble' }
];

export const getKeyboardCommands = (
    superGetKeyboardCommands: () => OpenFin.ShortcutOverride[]
): OpenFin.ShortcutOverride[] => {
    const manifestCommands = superGetKeyboardCommands();
    const overriddenCommands = new Set(manifestCommands.map((c) => c.command));
    const DEFAULT_COMMANDS = getIsEnterprisePlatform() ? ENTERPRISE_DEFAULT_COMMANDS : WORKSPACE_DEFAULT_COMMANDS;

    const effectiveDefaults = DEFAULT_COMMANDS.filter((cmd) => !overriddenCommands.has(cmd.command));

    return [...effectiveDefaults, ...manifestCommands];
};
