import { useEffect, useMemo } from 'react';
import { useDispatch } from 'react-redux';

import { OpenFin } from '@openfin/core';

import type { AttachedPageInternal } from '@common/api/pages/shapes';

import {
    onViewStoppedLoading,
    onViewUrlChanged,
    removePageState,
    setPageSingleViewState
} from '@enterprise/slices/pages-loading';

export function usePageLoadingEvents(page: AttachedPageInternal) {
    const dispatch = useDispatch();
    const { layoutContainerKey } = page;

    useEffect(() => {
        return () => {
            dispatch(removePageState({ layoutContainerKey }));
        };
    }, [layoutContainerKey, dispatch]);

    const singleViewIdentity = useMemo(
        () => (page.singleViewName ? { uuid: fin.me.uuid, name: page.singleViewName } : null),
        [page.singleViewName]
    );

    useEffect(() => {
        // Only run when it's a single view page
        if (!singleViewIdentity) {
            return;
        }

        let identityChanged = false;

        // getCurrentSync returns a View object that represents the current view
        // Since we are not only interested in the current view, but also in the loading events of other views,
        // we need to get the information about any existing views
        const view = fin.View.wrapSync(singleViewIdentity);
        const viewName = singleViewIdentity.name;

        // Stopping an event listener for the view => decrement the loading count
        function handleDidStopLoading() {
            dispatch(onViewStoppedLoading({ layoutContainerKey, viewName }));
        }

        // Equivalent to did-finish-load, but triggered when the page fails to load
        function handleDidFailLoad() {
            dispatch(onViewStoppedLoading({ layoutContainerKey, viewName }));
        }

        /**
         * If the user navigates to a new URL and it is NOT the landing page,
         * we consider it "loading." If it *is* the landing page, we remove from store to avoid a spinner.
         */
        async function handleUrlChanged(e: OpenFin.Events.WebContentsEvents.UrlChangedEvent) {
            try {
                /**
                 * Determines whether a navigation event is a full page load or an in-page navigation.
                 *
                 * - `isInPage: true` → The navigation happened **within the same page** without a full reload.
                 *   Examples: clicking an anchor link (`#section`), `window.location.hash`, or `history.pushState()`.
                 * - `isInPage: false` → A **full navigation or page reload** occurred.
                 *   Examples: entering a new URL, clicking a standard `<a>` link, refreshing the page, or a server redirect.
                 *
                 * This distinction helps avoid unnecessary loading indicators for in-page changes.
                 *
                 * Reference: OpenFin API - WebContentsEvents.UrlChangedEvent
                 * https://developers.openfin.co/docs/api/v27.91.67/webcontents#event-url-changed
                 */

                if (!e.isInPage) {
                    dispatch(onViewUrlChanged({ layoutContainerKey, viewName, url: e.url }));
                }
            } catch (err) {
                console.warn('Could not get view info:', err);
            }
        }

        // Attach the event listeners
        Promise.all([
            view.addListener('url-changed', handleUrlChanged),
            view.addListener('did-finish-load', handleDidStopLoading),
            view.addListener('did-fail-load', handleDidFailLoad)
        ]).then(async () => {
            // If the single view identity hasn't changed, check the view url just in case we missed the initial `url-changed`
            if (!identityChanged) {
                const info = await fin.View.wrapSync(singleViewIdentity).getInfo();
                // Views can have undefined URLS when initially created
                if (info.url.length) {
                    dispatch(
                        setPageSingleViewState({ layoutContainerKey, viewName: singleViewIdentity.name, url: info.url })
                    );
                }
            }
        });

        // Cleanup the event listeners
        return () => {
            identityChanged = true;
            view.removeListener('url-changed', handleUrlChanged);
            view.removeListener('did-finish-load', handleDidStopLoading);
            view.removeListener('did-fail-load', handleDidFailLoad);
        };
    }, [dispatch, singleViewIdentity, layoutContainerKey]);
}
