import { Dispatch, SetStateAction, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { OpenFin } from '@openfin/core';

import {
    BrowserSearchMenuKeyboardEvent,
    SearchMenuChannelMessage,
    SearchMenuChannelResponse,
    SelectableResult
} from '@common/utils/popup-window';
import { getCurrentOFWindow } from '@common/utils/window';

import { SearchMenuChannel } from '@enterprise/components/ControlBar/LeftControlsContainer/EnterpriseNavigationContainer/AddressBar/AddressBar';

import { getCurrentSync } from '@client-platform/api';
import { NavigationRequest, Site, SiteAction } from '@client-platform/shapes';
import { WindowSearchMenuContext } from '@enterprise/context/SearchMenu/WindowSearchMenuContext';

/**
 * Promise that resolves when the channel is ready to receive messages.
 */
export const searchViewReady = (() => {
    let resolve: () => void;
    const promise = new Promise<void>((res) => {
        resolve = res;
    });

    return { promise, resolve };
})();

const getFocusedItemTitle = (
    result: SelectableResult,
    t: (key: string, params?: Record<string, unknown>) => string
): string => {
    if ('type' in result && result.type === 'view-more-result') {
        return t('searchResults.viewMore');
        // It's a Site
    }
    return (result as Site).title || '';
};

/**
 * Custom hook that initializes a channel between the browser window and the search view to receive communications from the search view.
 * These messages include navigation requests, keyboard events to modify the search text while the search view is focused, and view resize requests,
 *
 * @param selectedViews - Array of currently selected views in the browser window.
 * @param selectedViewUrl - The URL of the currently selected view.
 * @param searchMenuChannel - Object containing a function to send messages to the search view.
 * @param setAddressBarWidth - Function that updates the width in pixels of the address input bar in its expanded state.
 * @param setShouldExpandMenu - Function that updates whether the menu should expand and the method of expansion.
 * @param setSearchText - Function that updates the search text in the address input.
 * @param resetAddressBarToSelectedViewUrl - Function that resets the address bar to the URL of the selected view.
 */
export const useInitChannelToSearchMenuView = (
    selectedViews: OpenFin.Identity[],
    selectedViewUrl: string,
    searchMenuChannel: SearchMenuChannel,
    setAddressBarWidth: Dispatch<SetStateAction<number>>,
    setSearchText: Dispatch<SetStateAction<string>>,
    resetAddressBarToSelectedViewUrl: () => void
) => {
    const { t } = useTranslation();
    const { setShouldExpandMenu, shouldExpandMenu } = useContext(WindowSearchMenuContext);
    const broadcastChannel = useRef<BroadcastChannel | null>(null);
    const [announcementMessage, setAnnouncementMessage] = useState<string | null>(null);

    const handleNavigation = useCallback(
        async (input: Site | string, view: OpenFin.Identity, trigger?: SiteAction) => {
            const navigationRequest: NavigationRequest =
                typeof input === 'string'
                    ? {
                          windowIdentity: fin.me.identity,
                          viewIdentity: view,
                          action: 'search-input',
                          query: input,
                          queryId: '',
                          providerId: ''
                      }
                    : {
                          windowIdentity: fin.me.identity,
                          viewIdentity: view,
                          action: 'result-selected',
                          site: input,
                          trigger: trigger
                      };

            if (selectedViews && selectedViews.length > 0) {
                const platform = getCurrentSync();
                const browserWin = platform.Browser.wrapSync(fin.me.identity);
                // eslint-disable-next-line no-underscore-dangle
                await browserWin._handleRequestNavigation(navigationRequest);
            } else {
                console.warn('`handleNavigation` was called without any selected views');
            }
        },
        [selectedViews]
    );

    const handleKeyFromView = useCallback(async (event: BrowserSearchMenuKeyboardEvent) => {
        await getCurrentOFWindow().focus();

        const { key, metaKey, ctrlKey, altKey } = event.options;
        if (key.length === 1) {
            setSearchText((searchText) => searchText + key);
        } else if (key === 'Backspace' && !metaKey && !ctrlKey && !altKey) {
            setSearchText((searchText) => searchText.slice(0, -1));
        } else if (key === 'Escape') {
            setShouldExpandMenu({ shouldExpand: false });
        }
    }, []);

    useEffect(() => {
        broadcastChannel.current ||= new BroadcastChannel(`search-menu-${fin.me.identity.name}`);
        searchMenuChannel.postMessage = async (message: SearchMenuChannelMessage) => {
            await searchViewReady.promise; // Wait for the channel to be ready before sending messages
            broadcastChannel.current.postMessage(message);
        };
        broadcastChannel.current.postMessage({ type: 'ready' } as SearchMenuChannelMessage);

        return () => {
            broadcastChannel.current?.close();
            broadcastChannel.current = null;
        };
    }, []);

    useEffect(() => {
        broadcastChannel.current.onmessage = (
            ev: MessageEvent<SearchMenuChannelResponse | SearchMenuChannelMessage>
        ) => {
            searchViewReady.resolve(); // after the first message is received, the channel is ready to send messages (sent by `useInitChannelToBrowserWindow.ts`)
            switch (ev.data.type) {
                case 'search-response':
                    if (ev.data.handled) {
                        setShouldExpandMenu({ shouldExpand: false });
                    } else if (ev.data.selectedSite) {
                        resetAddressBarToSelectedViewUrl();
                        setShouldExpandMenu({ shouldExpand: false });
                        handleNavigation(ev.data.selectedSite, ev.data.selectedView, ev.data.trigger);
                    }
                    break;
                case 'keyboard-event':
                    handleKeyFromView(ev.data.keyboardEvent);
                    break;
                case 'resize-view':
                    setAddressBarWidth(ev.data.width);
                    break;
                case 'search-provider-changed':
                    setSearchText((text) => (text === selectedViewUrl ? '' : text));
                    break;
                case 'update-search-menu-state':
                    // Collapse search menu when find-in-page opens, but only if menu is currently expanded
                    if (
                        ev.data.shouldExpandMenu &&
                        !ev.data.shouldExpandMenu.shouldExpand &&
                        shouldExpandMenu.shouldExpand
                    ) {
                        setShouldExpandMenu({ shouldExpand: false });
                    }
                    break;
                case 'focused-changed': {
                    const focusedTitle = getFocusedItemTitle(ev.data.payload, t);
                    if (focusedTitle) {
                        setAnnouncementMessage(t('searchResults.focused', { title: focusedTitle }));
                    } else {
                        setAnnouncementMessage(null);
                    }
                    break;
                }
                case 'all-providers-results-announcement':
                    setAnnouncementMessage(ev.data.message);
                    break;
                case 'single-provider-results-announcement':
                    setAnnouncementMessage(ev.data.message);
                    break;
            }
        };
    }, [broadcastChannel.current, selectedViewUrl, resetAddressBarToSelectedViewUrl, shouldExpandMenu.shouldExpand]);

    // Clear announcement when menu collapses
    useEffect(() => {
        if (!shouldExpandMenu.shouldExpand) {
            setAnnouncementMessage(null);
        }
    }, [shouldExpandMenu.shouldExpand]);

    return { announcementMessage };
};
