import React, { FC, useCallback, useState } from 'react';
import { useSelector } from 'react-redux';

import { Menu } from '@common/utils/menu';
import { RightMenuConfig } from '@common/utils/menu-config';

import { useTranslation } from '@common/api/i18next';

import { selectActivePage } from '@enterprise/slices/pages/attached';

import { BrowserButtonType } from '@client-platform/shapes';
import { useLanguageChange } from '@common/hooks/useLanguageChange';

import MenuButton from '../../../../MenuButton/MenuButton';
import { defaultButtonPropMap } from '../../../utils';
import { getLayoutsMenu } from '../../menus/menuConfig';
import { PredefinedIconUrl } from '../MenuButtonIcon';

interface Props {
    tooltip?: string;
    iconUrl?: string;
}

const LayoutsMenuButton: FC<Props> = ({ tooltip, iconUrl }) => {
    const [menuConfig, setMenuConfig] = useState<RightMenuConfig | null>(null);
    const customToolTip = tooltip || menuConfig?.title;
    const defaultIcon = defaultButtonPropMap[BrowserButtonType.PresetLayouts].iconProps.icon;
    const activePage = useSelector(selectActivePage);
    const disabled = !!activePage?.isLocked;
    const { t } = useTranslation();

    const onLanguageChange = useCallback(() => {
        const title = t('toolbar.changeLayout');
        getLayoutsMenu(title).then((menu) => setMenuConfig(menu));
    }, []);

    useLanguageChange(onLanguageChange);

    if (!menuConfig) {
        return null;
    }

    return (
        <MenuButton type={Menu.LAYOUT} config={menuConfig} params={null} tooltip={customToolTip} disabled={disabled}>
            <PredefinedIconUrl customIconUrl={iconUrl} uiLibIcon={defaultIcon} disabled={disabled} />
        </MenuButton>
    );
};

export default LayoutsMenuButton;
