import { FC, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { showSuccess } from '@common/utils/indicators/showIndicator';
import { getUnlockedLayout } from '@common/utils/layout';
import { browserLockButtonLockedState, browserLockButtonUnLockedState } from '@common/utils/test-ids';

import { useTranslation } from '@common/api/i18next';

import BaseButton from '@common/components/BaseButton/BaseButton';

import { selectActivePage, selectActivePageIndex, updatePageAtIndex } from '@enterprise/slices/pages/attached';

import { replaceLayout } from '@enterprise/utils/layout';

import { PredefinedIconUrl } from '@enterprise/components/ControlBar/RightControlsContainer/ToolbarContainer/buttons/MenuButtonIcon';

const LockUnlockButton: FC<{
    lockedIconUrl: string;
    unlockedIconUrl: string;
}> = ({ lockedIconUrl, unlockedIconUrl }) => {
    const dispatch = useDispatch();
    const activePage = useSelector(selectActivePage);
    const activePageIndex = useSelector(selectActivePageIndex);
    const windowName = activePage.parentIdentity;
    const buttonRef = useRef<HTMLButtonElement>(null);
    const { t } = useTranslation();

    const handleClick = async () => {
        const layout = fin.Platform.Layout.getCurrentSync();
        const layoutConfig = await layout.getConfig();
        // We always want to store the unlocked layout of the page in memory, this helps to make locking reversible
        const unlockedLayout = activePage.isLocked ? getUnlockedLayout(layoutConfig, activePage.layout) : layoutConfig;

        const updatedPage = {
            ...activePage,
            isLocked: !activePage.isLocked,
            layout: unlockedLayout
        };
        dispatch(
            updatePageAtIndex({
                index: activePageIndex,
                page: updatedPage
            })
        );
        await replaceLayout(unlockedLayout, updatedPage);
        await fin.me.focus();
        buttonRef.current?.focus();

        showSuccess({
            message: t(activePage.isLocked ? 'successIndicator.unlocked' : 'successIndicator.locked'),
            parentBrowserName: windowName.name
        });
    };

    return (
        <BaseButton
            ref={buttonRef}
            title={t(activePage.isLocked ? 'toolbar.unlock' : 'toolbar.lock')}
            onClick={handleClick}
        >
            {activePage.isLocked ? (
                <PredefinedIconUrl
                    customIconUrl={lockedIconUrl}
                    uiLibIcon="LockClosedIcon"
                    data-testid={browserLockButtonLockedState}
                />
            ) : (
                <PredefinedIconUrl
                    customIconUrl={unlockedIconUrl}
                    uiLibIcon="LockOpen1Icon"
                    data-testid={browserLockButtonUnLockedState}
                />
            )}
        </BaseButton>
    );
};

export default LockUnlockButton;
