import { useMemo } from 'react';
import { useSelector } from 'react-redux';

import { enterpriseStyles } from '@openfin/ui-library/enterprise-css-selectors';

import { currentOFIdentity } from '@common/utils/window';

import { selectIsWindows } from '@common/slices/environment';

import BaseButton from '@common/components/BaseButton/BaseButton';
import MacWindowStateButton from '@common/components/ControlButtons/MacWindowStateButton';
import { MaximizeButtonProps, toggleMaximize } from '@common/components/ControlButtons/MaximizeButton';
import { CustomIcon } from '@common/components/Icon/CustomIcon';

import useWindowFocusState from '@common/hooks/useWindowFocusState';
import { useWindowState } from '@common/hooks/useWindowState';
import { StyledIcon } from '@common/styles/svg-icons';
import { ThemedSVG } from '@enterprise/styles/ThemedSVG';

import '@openfin/ui-library/enterprise/window-controls/window-controls.css';

export const EnterpriseMaximizeButton = ({
    disabled = false,
    iconUrl,
    tooltip,
    parentHover,
    analyticsCallback
}: MaximizeButtonProps & {
    parentHover?: boolean;
}) => {
    const windowState = useWindowState();
    const windowFocused = useWindowFocusState();
    const isWindows = useSelector(selectIsWindows);
    const windowStateToolip = windowState === 'maximized' ? 'Restore Window' : 'Maximize Window';
    const icon = windowState === 'maximized' ? 'CopyIcon' : 'SquareIcon';
    const buttonTitle = tooltip ?? (disabled ? 'Disabled' : windowStateToolip);

    const onClick = analyticsCallback
        ? () => {
              analyticsCallback(tooltip, currentOFIdentity.name);
              toggleMaximize();
          }
        : toggleMaximize;

    const macClassName = useMemo(
        () =>
            windowFocused
                ? enterpriseStyles.windowControlsMacButtonMaximize
                : enterpriseStyles.windowControlsMacButtonInactive,
        [windowFocused]
    );

    if (isWindows) {
        return (
            <BaseButton title={buttonTitle} onClick={onClick} disabled={disabled} width={24} height={24}>
                {iconUrl && <CustomIcon iconURL={iconUrl} size="small" />}
                {!iconUrl && windowState === 'maximized' ? (
                    <StyledIcon disabled={disabled} isEnterprise={true} windowFocused={windowFocused}>
                        <RestoreIcon />
                    </StyledIcon>
                ) : (
                    <StyledIcon
                        disabled={disabled}
                        isEnterprise={true}
                        windowFocused={windowFocused}
                        icon={icon}
                        size="small"
                    />
                )}
            </BaseButton>
        );
    } else {
        return (
            <MacWindowStateButton
                className={macClassName}
                title={buttonTitle}
                onClick={onClick}
                disabled={disabled}
                width={12}
                height={12}
                hoverless
                borderRadius="small"
            >
                {windowFocused ? parentHover ? <MacExpandIconHover /> : <MacExpandIcon /> : <MacInactiveIcon />}
            </MacWindowStateButton>
        );
    }
};

const MacExpandIconHover = () => {
    return (
        <svg width="13" height="13" viewBox="0 0 13 13" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="6.38364" cy="6.01047" r="5.98953" fill="#62C554" />
            <path
                fillRule="evenodd"
                clipRule="evenodd"
                d="M3.6769 2.79613C3.39623 2.79533 3.1685 3.02306 3.1693 3.30373L3.18099 7.40988C3.1812 7.48492 3.27193 7.52235 3.325 7.46929L7.84246 2.95183C7.89552 2.89876 7.85809 2.80803 7.78305 2.80782L3.6769 2.79613ZM9.10118 9.2356C9.38185 9.23639 9.60958 9.00867 9.60878 8.728L9.59709 4.62185C9.59688 4.54681 9.50614 4.50937 9.45308 4.56243L4.93562 9.0799C4.88255 9.13296 4.91999 9.2237 4.99503 9.22391L9.10118 9.2356Z"
                fill="#296018"
            />
        </svg>
    );
};

const MacExpandIcon = () => {
    return (
        <svg width="13" height="13" viewBox="0 0 13 13" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="6.38364" cy="6.01047" r="5.98953" fill="#62C554" />
        </svg>
    );
};

const MacInactiveIcon = () => {
    return (
        <ThemedSVG width="12" height="12" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path
                fillRule="evenodd"
                clipRule="evenodd"
                d="M6 12C9.31371 12 12 9.31371 12 6C12 2.68629 9.31371 0 6 0C2.68629 0 0 2.68629 0 6C0 9.31371 2.68629 12 6 12Z"
                fill="white"
                fillOpacity="0.1"
            />
        </ThemedSVG>
    );
};

const RestoreIcon = () => {
    return (
        <ThemedSVG width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path
                d="M8.84211 4C7.94442 4 7.16649 4.51453 6.78207 5.26316H17.6842C18.2648 5.26316 18.7368 5.73516 18.7368 6.31579V17.2179C19.4855 16.8339 20 16.0556 20 15.1579V6.31579C20 5.03916 18.9608 4 17.6842 4H8.84211ZM6.31579 6.52632C5.04431 6.52632 4 7.57062 4 8.84211V17.6842C4 18.9557 5.04431 20 6.31579 20H15.1579C16.4294 20 17.4737 18.9557 17.4737 17.6842V8.84211C17.4737 7.57062 16.4294 6.52632 15.1579 6.52632H6.31579ZM6.31579 7.78947H15.1579C15.7466 7.78947 16.2105 8.25338 16.2105 8.84211V17.6842C16.2105 18.2729 15.7466 18.7368 15.1579 18.7368H6.31579C5.72706 18.7368 5.26316 18.2729 5.26316 17.6842V8.84211C5.26316 8.25338 5.72706 7.78947 6.31579 7.78947Z"
                fill="white"
            />
        </ThemedSVG>
    );
};
