import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import type OpenFin from '@openfin/core';

import type { BrowserWorkspacePlatformWindowOptions } from '@client-platform/shapes';

import { getInitialWindowOptions } from '@common/utils/initial-window-options';

type WindowOptionsContextValue = {
    workspacePlatform: BrowserWorkspacePlatformWindowOptions;
    windowIcon?: string;
    hasLoaded: boolean;
};

const defaultContextValue: WindowOptionsContextValue = {
    workspacePlatform: {} as BrowserWorkspacePlatformWindowOptions,
    windowIcon: undefined,
    hasLoaded: false
};

const WindowOptionsContext = createContext<WindowOptionsContextValue>(defaultContextValue);

/**
 * Provides window options to all descendants via context.
 * Pre-seeded with fin.__internal_.initialOptions for immediate availability.
 * Subscribes to options-changed before fetching getOptions() to avoid race conditions.
 *
 * NOTE: Initial state is always null to avoid hydration mismatches — fin APIs are
 * unavailable during static generation, so reading them in the useState initializer
 * produces different output on server vs client. The useEffect below seeds the real
 * values immediately after mount.
 */
export const WindowOptionsProvider = ({ children }: { children: React.ReactNode }) => {
    const [workspacePlatform, setWorkspacePlatform] = useState<BrowserWorkspacePlatformWindowOptions | null>(null);
    const [windowIcon, setWindowIcon] = useState<string | undefined>(undefined);

    useEffect(() => {
        const initial = getInitialWindowOptions();
        if (initial) {
            setWorkspacePlatform((initial.workspacePlatform as BrowserWorkspacePlatformWindowOptions) ?? null);
            setWindowIcon(initial.icon);
        }
    }, []);

    const handleOptionsChanged = useCallback((event: OpenFin.WindowEvents.WindowOptionsChangedEvent) => {
        if (event.diff?.workspacePlatform) {
            setWorkspacePlatform(event.options.workspacePlatform as BrowserWorkspacePlatformWindowOptions);
        }
        if (event.diff?.icon !== undefined) {
            setWindowIcon(event.options.icon);
        }
    }, []);

    useEffect(() => {
        const win = fin.Window.getCurrentSync();
        let receivedEventWhileFetching = false;

        const onOptionsChanged = (event: OpenFin.WindowEvents.WindowOptionsChangedEvent) => {
            receivedEventWhileFetching = true;
            handleOptionsChanged(event);
        };

        const init = async () => {
            // Subscribe to changes BEFORE fetching options to avoid race conditions
            await win.on('options-changed', onOptionsChanged);

            const options = await win.getOptions();

            // Only apply getOptions result if no event fired while fetching,
            // otherwise the event already set the newer values
            if (!receivedEventWhileFetching) {
                setWorkspacePlatform(options.workspacePlatform as BrowserWorkspacePlatformWindowOptions);
                setWindowIcon(options.icon);
            }
        };

        init();

        return () => {
            win.removeListener('options-changed', onOptionsChanged);
        };
    }, [handleOptionsChanged]);

    const value = useMemo<WindowOptionsContextValue>(
        () => ({
            workspacePlatform: workspacePlatform ?? ({} as BrowserWorkspacePlatformWindowOptions),
            windowIcon,
            hasLoaded: workspacePlatform !== null
        }),
        [workspacePlatform, windowIcon]
    );

    return <WindowOptionsContext.Provider value={value}>{children}</WindowOptionsContext.Provider>;
};

export const useWindowOptions = (): WindowOptionsContextValue => {
    return useContext(WindowOptionsContext);
};
