import { useCallback, useEffect } from 'react';

import type OpenFin from '@openfin/core';

interface UseKeyboardCommandsProps {
    commandListeners: Record<
        string,
        (
            e:
                | OpenFin.Events.PlatformEvents.ByType<'view-hotkey'>
                | OpenFin.Events.PlatformEvents.ByType<'window-hotkey'>
        ) => void
    >;
}

/**
 * Dispatches keyboard commands received via platform `view-hotkey` / `window-hotkey` events.
 */
export const useKeyboardCommands = ({ commandListeners }: UseKeyboardCommandsProps): void => {
    const handleCommand = useCallback(
        async (
            e:
                | OpenFin.Events.PlatformEvents.ByType<'view-hotkey'>
                | OpenFin.Events.PlatformEvents.ByType<'window-hotkey'>
        ) => {
            for (const [subscribedCommand, listener] of Object.entries(commandListeners)) {
                if (e.command === subscribedCommand) {
                    listener(e);
                    break;
                }
            }
        },
        [commandListeners]
    );

    useEffect(() => {
        const platform = fin.Platform.getCurrentSync();
        const currentWindow = (fin.me as OpenFin.Window).identity;

        const handleHotkey = (
            e:
                | OpenFin.Events.PlatformEvents.ByType<'view-hotkey'>
                | OpenFin.Events.PlatformEvents.ByType<'window-hotkey'>
        ) => {
            if ('viewIdentity' in e) {
                if (currentWindow.name !== e.target.name) return;
            } else {
                if (currentWindow.name !== e.name) return;
            }
            // TODO: CORE-2541 — fix at the source in Core's bubble-phase hotkey handler
            // so a prevented keyDown suppresses the paired keyUp for all bubble hotkeys.
            if (e.inputType !== 'keyDown') return;
            if (e.command) handleCommand(e);
        };

        platform.on('view-hotkey', handleHotkey);
        platform.on('window-hotkey', handleHotkey);

        return () => {
            platform.removeListener('view-hotkey', handleHotkey);
            platform.removeListener('window-hotkey', handleHotkey);
        };
    }, [handleCommand]);
};
