import { useEffect } from 'react';

const eventsToPropagate = ['tab-created', 'tab-dropped', 'container-created', 'tab-closed'];

export const usePropagateLayoutContainerEventsToParent = (containerRef: React.MutableRefObject<HTMLDivElement>) => {
    useEffect(() => {
        const container = containerRef.current;
        if (!container) {
            return;
        }

        const propagateEventToParent = (event: any) => {
            event.stopPropagation();
            if (!container.parentNode) return;
            const customEventForParent = new CustomEvent(event.type, {
                detail: { ...event.detail, originalElement: event.srcElement },
                bubbles: true
            });
            container.parentNode.dispatchEvent(customEventForParent);
        };

        eventsToPropagate.forEach((e) => container.addEventListener(e, propagateEventToParent));

        return () => {
            eventsToPropagate.forEach((e) => container.removeEventListener(e, propagateEventToParent));
        };
    }, [containerRef]);
};
