import { useEffect, useState } from 'react';

export type WindowState = 'maximized' | 'minimized' | 'normal';

export const useWindowState = (): WindowState => {
    const [windowState, setWindowState] = useState<WindowState>('normal');

    useEffect(() => {
        if (!fin) return;

        const currentWindow = fin.Window.getCurrentSync();

        const handleMaximized = () => setWindowState('maximized');
        const handleMinimized = () => setWindowState('minimized');
        const handleRestored = () => setWindowState('normal');

        currentWindow.on('maximized', handleMaximized);
        currentWindow.on('minimized', handleMinimized);
        currentWindow.on('restored', handleRestored);

        currentWindow.getState().then(setWindowState);

        return () => {
            currentWindow.removeListener('maximized', handleMaximized);
            currentWindow.removeListener('minimized', handleMinimized);
            currentWindow.removeListener('restored', handleRestored);
        };
    }, []);

    return windowState;
};
