import styled, { css } from 'styled-components';

import { MAC_WINDOW_BORDER_RADIUS } from '@common/mixins/padding-border';

import BaseButton from '../BaseButton/BaseButton';

import IconButton from './IconButton';

/** Matches the window frame top-right radius so hover does not square-cut past the chrome curve. */
const windowChromeCloseCorner = css`
    border-top-right-radius: ${MAC_WINDOW_BORDER_RADIUS};

    &:hover:not(:disabled),
    &:active:not(:disabled) {
        border-top-right-radius: ${MAC_WINDOW_BORDER_RADIUS};
    }
`;

export const WindowChromeCloseIconButton = styled(IconButton)`
    ${windowChromeCloseCorner}
`;

export const WindowChromeCloseBaseButton = styled(BaseButton)`
    ${windowChromeCloseCorner}
`;
